window.QUIZ_QUESTIONS = [{"id": 1, "section": "人工智能专题", "num": 1, "stem": "公认的人工智能元年是（ ）。", "options": [{"letter": "A", "text": "1950年"}, {"letter": "B", "text": "1936年"}, {"letter": "C", "text": "1956年"}, {"letter": "D", "text": "1946年"}], "answer": "C", "explanation": "1956年达特茅斯会议上，麦卡锡等人首次正式提出“人工智能”这一术语，人工智能作为一门独立学科由此诞生，因此1956年成为学科的起点。最易混淆的是1950年，图灵当年发表论文提出图灵测试，只是人工智能的重要思想先驱，并非学科创立的标志。"}, {"id": 2, "section": "人工智能专题", "num": 2, "stem": "人工智能发展有三种形态，其中智力与人类相当的形态是（ ）。", "options": [{"letter": "A", "text": "强人工智能"}, {"letter": "B", "text": "超人工智能"}, {"letter": "C", "text": "弱人工智能"}, {"letter": "D", "text": "泛人工智能"}], "answer": "A", "explanation": "人工智能按能力分为弱、强、超三类：弱人工智能只擅长特定任务，强人工智能在推理、学习等通用能力上与人类相当，能处理各类问题，超人工智能则全面超越人类。因此选强人工智能。最易混淆的是超人工智能，它并非与人类相当，而是远超人类水平。"}, {"id": 3, "section": "人工智能专题", "num": 3, "stem": "新一代信息技术包含（ ）。", "options": [{"letter": "A", "text": "大数据"}, {"letter": "B", "text": "云计算"}, {"letter": "C", "text": "物联网"}, {"letter": "D", "text": "以上都是"}], "answer": "D", "explanation": "新一代信息技术是以数字化、网络化、智能化为特征的技术群，涵盖大数据、云计算、物联网、人工智能、5G等，它们相互支撑、协同发展，共同构成数字经济的基础设施。因此三项都属于该范畴，应选“以上都是”。容易误选单项，是因为只看到某一技术的代表性，却忽略了新一代信息技术是多技术融合的集合概念而非单一技术。"}, {"id": 4, "section": "人工智能专题", "num": 4, "stem": "2016年3月，人工智能程序( )在韩国首尔以4:1的比分战胜的人类围棋冠军李世石。", "options": [{"letter": "A", "text": "AlphaGo"}, {"letter": "B", "text": "AlphaGo Zero"}, {"letter": "C", "text": "Deepblue"}, {"letter": "D", "text": "DeepMind"}], "answer": "A", "explanation": "AlphaGo是DeepMind开发的围棋程序，融合深度学习与蒙特卡洛树搜索，能在巨大棋局空间中评估落子并取得突破性胜利。最易混淆的是AlphaGo Zero，它是2017年才推出、无需人类棋谱仅靠自我对弈训练的升级版，并非当年参赛者。"}, {"id": 5, "section": "人工智能专题", "num": 5, "stem": "在AI技术的四要素中，（ ）蕴含着应用背景中的知识和经验。", "options": [{"letter": "A", "text": "数据"}, {"letter": "B", "text": "算力"}, {"letter": "C", "text": "场景"}, {"letter": "D", "text": "算法"}], "answer": "C", "explanation": "人工智能四要素包括数据、算力、算法和场景，场景是技术落地的具体应用环境，蕴含行业背景、业务规则与专家经验，因而是知识经验的载体。最易混淆的是数据，它只记录客观事实与信息，本身不包含应用背景，只有置于场景中才有意义。"}, {"id": 6, "section": "人工智能专题", "num": 6, "stem": "以下选项中，不是图像识别基本任务的是（ ）。", "options": [{"letter": "A", "text": "定位"}, {"letter": "B", "text": "目标检测"}, {"letter": "C", "text": "分类"}, {"letter": "D", "text": "图像压缩"}], "answer": "D", "explanation": "图像识别的基本任务是对图像内容进行语义理解，包括分类、定位和目标检测。图像压缩属于图像编码与存储技术，目的是减少数据量以便传输和保存，并不判断图像中有什么，因此不属于图像识别任务。最容易混淆的是目标检测，它不是与定位、分类并列的独立操作，而是同时完成定位与分类的综合任务。"}, {"id": 7, "section": "人工智能专题", "num": 7, "stem": "（ ）是将输入的人脸和一个集合中的所有人脸进行比对，根据比对后的相似度对集合中的人脸进行排序。", "options": [{"letter": "A", "text": "人脸聚类"}, {"letter": "B", "text": "人脸验证"}, {"letter": "C", "text": "人脸比对"}, {"letter": "D", "text": "人脸检索"}], "answer": "D", "explanation": "人脸检索属于1:N的识别任务，先提取输入人脸特征，再与人脸库中全部样本计算相似度并按得分从高到低排序，返回最相似的若干结果，因此符合题意。最易混淆的是人脸比对，它通常指1:1判断两张人脸是否为同一人，只给出是或否，而不做全库排序。"}, {"id": 8, "section": "人工智能专题", "num": 8, "stem": "下列不属于自然语言处理应用的是（ ）。", "options": [{"letter": "A", "text": "机器翻译"}, {"letter": "B", "text": "情感分析"}, {"letter": "C", "text": "文本分类"}, {"letter": "D", "text": "身份证识别"}], "answer": "D", "explanation": "自然语言处理的核心是让计算机理解、分析与生成人类语言。机器翻译、情感分析、文本分类都直接处理语言的语义与结构，而身份证识别的核心是图像识别与OCR，只是将图片中的文字提取出来，并不进行语言理解与语义分析，所以它不属于自然语言处理。最容易混淆的是身份证识别，它虽涉及文字，但本质上属于计算机视觉，而非语言处理。"}, {"id": 9, "section": "人工智能专题", "num": 9, "stem": "下列不属于图像识别应用的是（ ）。", "options": [{"letter": "A", "text": "车牌识别"}, {"letter": "B", "text": "瑕疵检测"}, {"letter": "C", "text": "机器翻译"}, {"letter": "D", "text": "医疗影像诊断"}], "answer": "C", "explanation": "图像识别的核心是让计算机从图像或视频中提取特征并理解内容，属于计算机视觉范畴。车牌识别、瑕疵检测和医疗影像诊断都以图像为输入并输出识别或分类结果，因此属于图像识别；机器翻译则以文本为输入输出另一种语言的文本，属于自然语言处理而非图像识别。医疗影像诊断最易混淆，但它处理的是CT、X光等影像，仍属图像识别。"}, {"id": 10, "section": "人工智能专题", "num": 10, "stem": "人工智能的目的是让机器能够（ ），以实现某些脑力劳动的机械化。", "options": [{"letter": "A", "text": "完全替代人脑"}, {"letter": "B", "text": "模拟、延伸和扩展人的智能"}, {"letter": "C", "text": "完全替代人的思维"}, {"letter": "D", "text": "完全替代人"}], "answer": "B", "explanation": "人工智能的核心是研究如何用机器模拟人的智能活动，并在此基础上延伸和扩展人的能力，提升人处理信息与解决问题的效率。它强调辅助与增强人，而非取代人。最易混淆的是A，它把“模拟、延伸”偷换为“完全替代人脑”，夸大了AI的目标，忽略了人机协同与人的主体地位。"}, {"id": 11, "section": "人工智能专题", "num": 11, "stem": "以下不是人工智能四要素的是（ ）", "options": [{"letter": "A", "text": "智能"}, {"letter": "B", "text": "算法"}, {"letter": "C", "text": "算力"}, {"letter": "D", "text": "数据"}], "answer": "A", "explanation": "人工智能四要素是数据、算法、算力与场景，四者共同支撑人工智能系统落地，其中数据提供原料，算法提供方法，算力提供支撑，场景提供应用。智能是人工智能追求的目标和表现，而非构成要素，因此选A。容易混淆的是算法，常误以为它是智能本身，实际上算法只是实现智能的手段。"}, {"id": 12, "section": "人工智能专题", "num": 12, "stem": "在AI主要研究内容中，（ ）是人工智能研究中最重要也是最为关键的研究内容。", "options": [{"letter": "A", "text": "机器思维"}, {"letter": "B", "text": "机器学习"}, {"letter": "C", "text": "知识表示"}, {"letter": "D", "text": "机器感知"}], "answer": "A", "explanation": "机器思维是人工智能的核心目标，即让机器模拟人类推理、判断与决策等高级认知活动，是其他研究内容的最终指向。机器学习、知识表示与机器感知都是实现这一目标的手段或基础，而非目标本身。最易混淆的是机器学习，它虽是当前最热门、最实用的技术路径，但只是让机器获得能力的学习方法，不能等同于思维本身。"}, {"id": 13, "section": "人工智能专题", "num": 13, "stem": "下列不属于智能语音应用的是（ ）。", "options": [{"letter": "A", "text": "苹果的Siri"}, {"letter": "B", "text": "微软的Cortanna"}, {"letter": "C", "text": "身份证识别"}, {"letter": "D", "text": "智能音箱"}], "answer": "C", "explanation": "智能语音应用的核心是语音识别、语音合成与自然语言理解，以语音作为交互入口。苹果语音助手、微软小娜和智能音箱都通过语音接收指令并反馈，属于此类；身份证识别属于图像识别与文字识别，处理图像信息而非语音信号。最容易混淆的是智能音箱，它看似硬件，但核心仍是语音助手与语音交互，所以属于智能语音应用。"}, {"id": 14, "section": "人工智能专题", "num": 14, "stem": "以下哪一种生理电信号可以用于情绪识别（ ）。", "options": [{"letter": "A", "text": "眼电"}, {"letter": "B", "text": "脑电"}, {"letter": "C", "text": "心电"}, {"letter": "D", "text": "肌电"}], "answer": "B", "explanation": "情绪由大脑边缘系统等中枢活动直接调控，脑电能反映不同情绪下脑区激活与节律的变化，因而是情绪识别最直接、常用的生理信号。心电虽能反映情绪引起的自主神经变化，如心率加快，但它主要表征心脏活动而非情绪本身，容易被误认为可直接识别情绪。"}, {"id": 15, "section": "人工智能专题", "num": 15, "stem": "（ ）不属于人工智能应用领域。", "options": [{"letter": "A", "text": "智能搜索引擎"}, {"letter": "B", "text": "3D打印"}, {"letter": "C", "text": "人脸识别"}, {"letter": "D", "text": "自动驾驶"}], "answer": "B", "explanation": "人工智能应用指机器通过学习数据实现感知、理解与自主决策。智能搜索、人脸识别、自动驾驶分别依赖自然语言处理、计算机视觉与感知决策，是典型应用；3D打印只是按数字模型逐层堆积成型的增材制造，本身没有学习与决策能力。最易混淆的是智能搜索引擎，其排序推荐依赖智能算法，并非普通检索。"}, {"id": 16, "section": "人工智能专题", "num": 16, "stem": "人工智能（AI）是（ ）。", "options": [{"letter": "A", "text": "一种新型疾病"}, {"letter": "B", "text": "一种计算机技术"}, {"letter": "C", "text": "一种食物"}, {"letter": "D", "text": "一种交通工具"}], "answer": "B", "explanation": "人工智能是研究、开发能够模拟、延伸和扩展人类智能的理论、方法、技术及应用系统的计算机技术，它以算法、算力和数据为基础，让机器实现感知、推理、学习与决策，而非某种实体事物。A、C、D把抽象的技术概念误当成了具体事物，其中A最易受“智能”一词联想干扰，但AI本身并非生物体或疾病。"}, {"id": 17, "section": "人工智能专题", "num": 17, "stem": "人工智能中的“机器学习”是（ ）。", "options": [{"letter": "A", "text": "机器人上学"}, {"letter": "B", "text": "使用算法让计算机从数据中学习"}, {"letter": "C", "text": "让机器人学会唱歌"}, {"letter": "D", "text": "给计算机安装电池"}], "answer": "B", "explanation": "机器学习的核心是让计算机通过算法从大量数据中发现规律、提升性能，而非由人工逐条编写规则，因此B正确。最容易混淆的是A，它把“学习”拟人化为上学，忽略了其本质是数据驱动的统计建模与泛化。"}, {"id": 18, "section": "人工智能专题", "num": 18, "stem": "下列技术与自然语言处理（NLP）有关的是（ ）。", "options": [{"letter": "A", "text": "无人驾驶汽车"}, {"letter": "B", "text": "语音识别"}, {"letter": "C", "text": "脑电波控制"}, {"letter": "D", "text": "3D打印"}], "answer": "B", "explanation": "自然语言处理是让计算机理解、生成和处理人类语言的技术，核心在于语言的理解与交互。语音识别将人说的话转写为文字，是语言输入的关键环节，因此属于NLP。无人驾驶汽车最易混淆，它主要依赖计算机视觉与路径规划，核心并非语言处理。"}, {"id": 19, "section": "人工智能专题", "num": 19, "stem": "图像识别技术可以用来做（ ）。", "options": [{"letter": "A", "text": "预测股市"}, {"letter": "B", "text": "翻译语言"}, {"letter": "C", "text": "识别图片中的物体"}, {"letter": "D", "text": "制作美食"}], "answer": "C", "explanation": "图像识别属于计算机视觉，核心是通过算法从图像中提取特征并分类、定位其中的物体，因此可直接用于识别图片中的物体。最容易混淆的是B，语言翻译属于自然语言处理，处理的是文本或语音语义，而非图像内容。"}, {"id": 20, "section": "人工智能专题", "num": 20, "stem": "（ ）是神经网络。", "options": [{"letter": "A", "text": "一种交通网络"}, {"letter": "B", "text": "一种生物体内的神经系统"}, {"letter": "C", "text": "一种模拟人脑结构的计算模型"}, {"letter": "D", "text": "一种编程语言"}], "answer": "C", "explanation": "神经网络是人工智能中受人脑启发的计算模型，由大量相互连接的人工神经元组成，通过权重调整和学习从数据中提取规律、完成分类与预测等任务，因此C正确。最易混淆的是B，它指的是真实生物体内的神经系统，而非人工构建的数学模型。"}, {"id": 21, "section": "人工智能专题", "num": 21, "stem": "计算机视觉主要研究（ ）。", "options": [{"letter": "A", "text": "计算机硬件"}, {"letter": "B", "text": "从视觉信息中提取有意义的信息"}, {"letter": "C", "text": "计算机程序设计"}, {"letter": "D", "text": "计算机游戏开发"}], "answer": "B", "explanation": "计算机视觉是人工智能的重要分支，目标是让机器像人一样“看懂”图像和视频，从中提取物体、场景、动作等有意义的信息，用于识别、检测与理解，而非制造设备本身。程序设计只是实现算法的工具，不是研究对象，因此不能选C。"}, {"id": 22, "section": "人工智能专题", "num": 22, "stem": "下列属于著名的人工智能语音助手的是（ ）。", "options": [{"letter": "A", "text": "阿狸"}, {"letter": "B", "text": "阿尔法狗"}, {"letter": "C", "text": "Siri"}, {"letter": "D", "text": "美猴王"}], "answer": "C", "explanation": "语音助手是能通过语音识别与自然语言处理理解指令、完成对话交互与任务执行的人工智能应用，Siri作为苹果公司的语音助手，可通过语音完成查询、提醒、日程管理等，正是其典型代表。阿尔法狗最容易混淆，它虽是著名人工智能，但属于基于深度学习的围棋程序，并不具备语音交互功能。"}, {"id": 23, "section": "人工智能专题", "num": 23, "stem": "人脸识别技术的主要应用场景是（ ）。", "options": [{"letter": "A", "text": "安全与身份验证"}, {"letter": "B", "text": "气候变化研究"}, {"letter": "C", "text": "食品安全检测"}, {"letter": "D", "text": "航天探索"}], "answer": "A", "explanation": "人脸识别属于计算机视觉中的生物特征识别技术，通过提取面部特征并与数据库比对实现身份确认，因此主要应用于门禁、支付、安防等安全与身份验证场景。气候变化研究主要依赖遥感与气象数据建模，与面部特征无关，最容易被误认为相关的是B选项，其实它并不涉及对人的身份识别。"}, {"id": 24, "section": "人工智能专题", "num": 24, "stem": "下列是一种用于文本生成的AI模型的是（ ）。", "options": [{"letter": "A", "text": "ResNet"}, {"letter": "B", "text": "LSTM"}, {"letter": "C", "text": "GPT"}, {"letter": "D", "text": "AlexNet"}], "answer": "C", "explanation": "GPT是基于Transformer解码器结构的大语言模型，采用自回归方式逐词预测下一个词，因此是当前主流的文本生成模型。最容易混淆的LSTM虽能处理序列数据、用于文本理解或预测，但其结构与规模决定了它并非现代大规模文本生成的主流模型。"}, {"id": 25, "section": "人工智能专题", "num": 25, "stem": "当我们谈论AI伦理时，以下（ ）原则不应被包括。", "options": [{"letter": "A", "text": "公平性"}, {"letter": "B", "text": "透明度"}, {"letter": "C", "text": "可解释性"}, {"letter": "D", "text": "无限制监控"}], "answer": "D", "explanation": "AI伦理的核心是约束技术滥用、保障人的权利与尊严，要求算法公平、不歧视，决策过程透明、可被理解和问责，因此公平性、透明度、可解释性都是基本原则。无限制监控则侵犯隐私与自主权，与伦理背道而驰，故不应包括。最容易混淆的是透明度，它指公开算法逻辑与数据使用以便监督，而非对个人进行无死角监视。"}, {"id": 26, "section": "人工智能专题", "num": 26, "stem": "在AI领域，决策树常用于（ ）任务。", "options": [{"letter": "A", "text": "图像处理"}, {"letter": "B", "text": "语音合成"}, {"letter": "C", "text": "分类和回归"}, {"letter": "D", "text": "文本翻译"}], "answer": "C", "explanation": "决策树通过对特征逐层划分形成树形规则，叶子节点输出类别或连续数值，因此是典型的监督学习模型，天然适用于分类和回归任务。最容易混淆的图像处理主要依赖卷积神经网络提取像素特征，决策树难以直接处理高维图像数据。"}, {"id": 27, "section": "人工智能专题", "num": 27, "stem": "聊天机器人（Chatbot）通常用于（ ）场景。", "options": [{"letter": "A", "text": "驾驶汽车"}, {"letter": "B", "text": "拍摄电影"}, {"letter": "C", "text": "客户服务和支持"}, {"letter": "D", "text": "烹饪美食"}], "answer": "C", "explanation": "聊天机器人是基于自然语言处理的人机对话系统，擅长理解用户意图并以文本或语音自动回复，因此最适合处理高频、重复的咨询与售后问题。驾驶汽车虽然也是人工智能应用，但依赖感知、决策与运动控制，属于自动驾驶技术，并非对话交互的范畴。"}, {"id": 28, "section": "人工智能专题", "num": 28, "stem": "人工智能中的“模型”是（ ）。", "options": [{"letter": "A", "text": "模拟人体结构的机器人"}, {"letter": "B", "text": "演示AI技术的展示项目"}, {"letter": "C", "text": "从数据中学习和做出预测的算法和数据结构"}, {"letter": "D", "text": "一种模型飞机"}], "answer": "C", "explanation": "模型本质上是经过训练得到的、可用于推理的数学表达与参数集合，它通过从大量数据中学习规律，进而对新输入做出预测或分类，因此正确答案强调学习与预测功能。最容易混淆的是A，机器人只是模型可能部署的载体或应用形态，并非模型本身。"}, {"id": 29, "section": "人工智能专题", "num": 29, "stem": "在AI领域，以下（ ）技术与智能家居设备有关。", "options": [{"letter": "A", "text": "物联网（IoT）"}, {"letter": "B", "text": "密码学"}, {"letter": "C", "text": "数据压缩"}, {"letter": "D", "text": "生成对抗网络（GAN）"}], "answer": "A", "explanation": "物联网通过传感器、网络把灯具、空调、门锁等家居设备连接成统一系统，实现互联互通、远程控制与数据采集，是智能家居的核心支撑技术。生成对抗网络最易混淆，它主要用于图像、文本等内容的生成，并不负责设备联网与协同控制。"}, {"id": 30, "section": "人工智能专题", "num": 30, "stem": "以下（ ）技术与AI在农业领域的应用有关。", "options": [{"letter": "A", "text": "精准农业"}, {"letter": "B", "text": "图像分割"}, {"letter": "C", "text": "语音合成"}, {"letter": "D", "text": "色彩识别"}], "answer": "A", "explanation": "精准农业是AI在农业领域的典型应用场景，它通过传感器、卫星遥感与大数据分析实现土壤、墒情、病虫害的精细监测与变量施肥灌溉，从而提升产量并节约资源。图像分割虽是通用视觉技术，也可用于作物识别，但它本身是底层算法而非农业专属应用场景，容易与之混淆。"}, {"id": 31, "section": "人工智能专题", "num": 31, "stem": "下列技术与AI在天气预报领域的应用有关的是（ ）。", "options": [{"letter": "A", "text": "预测模型"}, {"letter": "B", "text": "语音合成"}, {"letter": "C", "text": "图像识别"}, {"letter": "D", "text": "色彩识别"}], "answer": "A", "explanation": "天气预报的核心是利用历史气象数据训练模型，推断未来温度、降水等趋势，因此预测模型是AI在该领域最直接的应用。图像识别虽可辅助分析卫星云图，但并非预报本身的核心技术，容易与之混淆。"}, {"id": 32, "section": "人工智能专题", "num": 32, "stem": "当人们谈论AI的“偏见”时，人们主要关心（ ）。", "options": [{"letter": "A", "text": "AI模型对某些群体或特征的不公正处理"}, {"letter": "B", "text": "AI模型的预测准确性"}, {"letter": "C", "text": "AI模型的计算速度"}, {"letter": "D", "text": "AI模型的技术复杂度"}], "answer": "A", "explanation": "AI偏见属于伦理与公平性问题，指模型因训练数据失衡或特征选择不当，对性别、种族、年龄等群体产生系统性歧视或不公正对待，因此选A。最容易混淆的是B，预测准确性是性能指标，整体准确率高仍可能对少数群体不公平，二者不能等同。"}, {"id": 33, "section": "人工智能专题", "num": 33, "stem": "下列技术与AI在医疗领域的应用有关的是（ ）。", "options": [{"letter": "A", "text": "疾病预测和诊断"}, {"letter": "B", "text": "聊天机器人"}, {"letter": "C", "text": "自动驾驶"}, {"letter": "D", "text": "线上挂号"}], "answer": "A", "explanation": "AI在医疗的核心应用是利用机器学习分析影像、病历与基因等数据，辅助医生进行疾病风险预测与诊断，提高准确率与效率，因此A正确。最易混淆的是D，线上挂号只是将传统挂号流程搬到网上，属于信息化手段，并未运用学习、推理等智能算法，不能等同于AI应用。"}, {"id": 34, "section": "人工智能专题", "num": 34, "stem": "机器通过人类发现的问题空间的数据，进行机器学习，具有在人类发现的问题空间中求解的能力，并且求解的过程与结果可以被人类智能（ ），此为机器智能的产生。", "options": [{"letter": "A", "text": "采纳"}, {"letter": "B", "text": "参考"}, {"letter": "C", "text": "理解"}, {"letter": "D", "text": "相同"}], "answer": "C", "explanation": "机器智能的核心在于可理解性：机器能从数据中学习并求解，但只有其过程与结果能被人类理解，才能被检验、信任与改进，实现真正的人机协同而非机器替代人类。最易混淆的是A项“采纳”，采纳只是接受结果，并不等于理解其依据和过程。"}, {"id": 35, "section": "人工智能专题", "num": 35, "stem": "当谈论AI时，数据科学家们经常提到“训练集”和“测试集”是（ ）意思。", "options": [{"letter": "A", "text": "用于训练和评估机器学习模型的数据子集"}, {"letter": "B", "text": "用于存储数据的磁盘空间"}, {"letter": "C", "text": "不同类型的数据集市"}, {"letter": "D", "text": "用于加密和解密数据的算法"}], "answer": "A", "explanation": "训练集与测试集是机器学习中划分原始数据的两个子集：训练集用于让模型学习数据规律、调整参数，测试集则用于在未见过的数据上评估模型的泛化能力，从而避免只看训练效果而高估模型。最易混淆的是C，数据集市是面向业务主题的数据仓库子集，而训练集与测试集只是为建模划分的数据样本。"}, {"id": 36, "section": "人工智能专题", "num": 36, "stem": "在最初的图灵测试中，如果有超过（ ）的测试者不能确定出被测试者是人还是机器，则这台机器就通过了测试，并认为具有人类智能。", "options": [{"letter": "A", "text": "20%"}, {"letter": "B", "text": "30%"}, {"letter": "C", "text": "40%"}, {"letter": "D", "text": "50%"}], "answer": "B", "explanation": "图灵于1950年提出图灵测试作为判断机器智能的操作性标准，并预言机器在五分钟对话后能让超过30%的提问者无法正确分辨，即可视为通过。这一比例是图灵的预测值，并非随意设定的及格线。最易误选D项50%，因常误以为须骗过半数以上才算通过，其实通过门槛低于半数。"}, {"id": 37, "section": "人工智能专题", "num": 37, "stem": "（ ）年由十几位青年学者参与的达特茅斯暑期研讨会上诞生了“人工智能”。", "options": [{"letter": "A", "text": "1954"}, {"letter": "B", "text": "1955"}, {"letter": "C", "text": "1956"}, {"letter": "D", "text": "1957"}], "answer": "C", "explanation": "1956年达特茅斯会议由麦卡锡等人发起，首次正式提出“人工智能”这一术语，标志着该学科的诞生，因此选C。1955年只是麦卡锡等人提交会议提案、筹备研讨会的年份，并非会议召开和术语诞生的时间，容易与1956年混淆。"}, {"id": 38, "section": "人工智能专题", "num": 38, "stem": "人工智能在医疗领域读片的过程体现为（ ）。", "options": [{"letter": "A", "text": "信息-传递-判断"}, {"letter": "B", "text": "图像解释-图像获取-图像分析"}, {"letter": "C", "text": "图像获取-图像解释-感知结果"}, {"letter": "D", "text": "图像获取-图像处理"}], "answer": "C", "explanation": "医疗读片属于人工智能感知过程，遵循先获取信息、再理解信息、最后输出结果的逻辑。图像获取是采集影像数据，图像解释是对影像内容进行识别与理解，感知结果则是形成的诊断辅助结论，三者顺序不可颠倒。最容易混淆的是D，它只停留在获取与处理，未完成解释并输出感知结果，因而不完整。"}, {"id": 39, "section": "人工智能专题", "num": 39, "stem": "计算机（ ）编程语言常常会应用于人工智能的开发库。", "options": [{"letter": "A", "text": "C++"}, {"letter": "B", "text": "Python"}, {"letter": "C", "text": "JAVA"}, {"letter": "D", "text": "Delphy"}], "answer": "B", "explanation": "Python 是人工智能开发的主流语言，语法简洁、生态完善，拥有 TensorFlow、PyTorch、scikit-learn 等开源库，能降低模型搭建与数据处理门槛，因而成为 AI 开发库的首选接口语言。最容易混淆的是 C++，它虽用于底层框架和高性能计算，但开发效率与库生态不如 Python，通常不作为应用层开发的首选。"}, {"id": 40, "section": "人工智能专题", "num": 40, "stem": "人工智能算法是建立在（ ）基础上。", "options": [{"letter": "A", "text": "四进位制"}, {"letter": "B", "text": "二进位制"}, {"letter": "C", "text": "六进位制"}, {"letter": "D", "text": "十二进位制"}], "answer": "B", "explanation": "人工智能算法最终要在计算机上运行，而计算机硬件以高低电平两种状态工作，只能直接识别0和1，因此所有数据、指令与逻辑运算都要先转化为二进制表示和处理，这是其底层基础。其他进制只是人为的计数或表示方式，并不能作为计算机的物理运行基础，尤其四进制看似与二进制接近，却同样无法直接对应电路的两种状态。"}, {"id": 41, "section": "人工智能专题", "num": 41, "stem": "下列叙述不正确的是（ ）。", "options": [{"letter": "A", "text": "图灵测试混淆了智能和人类的关系"}, {"letter": "B", "text": "机器智能的机制必须与人类智能相同"}, {"letter": "C", "text": "机器智能可以完全在特定的领域中超越人类智能"}, {"letter": "D", "text": "机器智能可以有人类智能的创造力"}], "answer": "B", "explanation": "人工智能追求功能等价而非机制相同，图灵测试只看行为表现是否像人，不要求内部过程与人脑一致，因此“必须相同”过于绝对。机器在围棋、图像识别等特定领域已超越人类，也能通过生成式模型产出新颖作品，具有一定创造力。最易误选的是D，创造力并非人类专属，机器的创造源于对已有模式的学习与重组，并非凭空产生。"}, {"id": 42, "section": "人工智能专题", "num": 42, "stem": "机器人的三定律中第一条是（ ）。", "options": [{"letter": "A", "text": "机器人不得伤害人类个体,或者目睹人类个体将遭受危险而袖手不管"}, {"letter": "B", "text": "机器人必须服从人给予它的命令"}, {"letter": "C", "text": "机器人要尽可能保护自己的生存"}, {"letter": "D", "text": "机器人必须保护人类的整体利益不受伤害"}], "answer": "A", "explanation": "阿西莫夫机器人三定律以人的安全为最高优先级，第一定律要求机器人不得伤害人类个体，也不得因不作为而使人受害，这是其余定律的前提。容易混淆的是D，它表述的是后来补充的第零定律，针对人类整体而非个体，优先级虽更高却不属于三定律的第一条。"}, {"id": 43, "section": "人工智能专题", "num": 43, "stem": "人和机器最大的区别是（ ）。", "options": [{"letter": "A", "text": "能动性"}, {"letter": "B", "text": "人性"}, {"letter": "C", "text": "思维"}, {"letter": "D", "text": "计算"}], "answer": "B", "explanation": "人性是人区别于机器的根本标志，涵盖情感、道德、价值判断与社会性等人所特有的属性，机器即使具备学习与推理能力，也无法真正拥有这些内在体验。思维最容易混淆，人工智能已能模拟推理、学习与决策，但这只是对思维过程的模拟，并非真正的人类思维。"}, {"id": 44, "section": "人工智能专题", "num": 44, "stem": "在AI领域，下列技术与自动驾驶汽车有关的是（ ）。", "options": [{"letter": "A", "text": "路径规划和决策"}, {"letter": "B", "text": "图像识别"}, {"letter": "C", "text": "语音识别"}, {"letter": "D", "text": "数据压缩"}], "answer": "A", "explanation": "自动驾驶的核心在于感知环境后作出行驶决策，路径规划与决策直接决定车辆如何行驶、避障与选择路线，是其决策层关键技术。最易混淆的是图像识别，它主要用于识别路标、行人等环境信息，属于感知环节的通用技术，并非自动驾驶特有的决策技术。"}, {"id": 45, "section": "人工智能专题", "num": 45, "stem": "通过计算样本个体或样本类之间的相似程度，将满足相似条件的样本个体或样本类分入同一类（簇）内属于（ ）。", "options": [{"letter": "A", "text": "分类"}, {"letter": "B", "text": "聚类"}, {"letter": "C", "text": "回归"}, {"letter": "D", "text": "训练"}], "answer": "B", "explanation": "聚类是无监督学习方法，不依赖标注标签，通过距离或相似度度量发现数据内在结构，把相似样本归为一簇、差异大的分开，从而实现无标签数据的分组。最易混淆的是分类，它是有监督学习，需用带标签样本训练模型，再把新样本分到已知类别中，与聚类发现未知类别不同。"}, {"id": 46, "section": "人工智能专题", "num": 46, "stem": "人工智能模仿人类不能局限于模仿人类自然维度,还需要考虑（ ）维度。", "options": [{"letter": "A", "text": "精神"}, {"letter": "B", "text": "经济"}, {"letter": "C", "text": "社会"}, {"letter": "D", "text": "文化"}], "answer": "D", "explanation": "人类智能不仅源于生理与感知等自然属性，更是在语言、价值观念、习俗与知识传承等文化环境中形成的，因此人工智能要真正模仿人类，必须纳入文化维度。社会维度易被混淆，但它主要指人际关系与社会结构，而文化才是决定行为方式与意义理解的深层背景。"}, {"id": 47, "section": "人工智能专题", "num": 47, "stem": "当前图像识别已经被广泛应用到各个领域中，下列不属于图像识别应用领域的是（ ）。", "options": [{"letter": "A", "text": "交通领域中的车牌号识别"}, {"letter": "B", "text": "军事领域中的飞行物识别"}, {"letter": "C", "text": "安全领域中的指纹识别"}, {"letter": "D", "text": "汽车领域中的智能车载"}], "answer": "D", "explanation": "图像识别是计算机视觉技术，通过提取、比对图像中的目标特征实现分类与识别。车牌、飞行物与指纹识别均基于图像特征分析，属于典型应用；而智能车载是集导航、语音、娱乐等功能于一体的综合系统，并非专门的图像识别应用，故D正确。最易混淆的是指纹识别，它看似生物验证，实则是采集指纹图像并比对纹路特征完成的识别。"}, {"id": 48, "section": "人工智能专题", "num": 48, "stem": "下列不属于图像识别发展所经历阶段的是（ ）。", "options": [{"letter": "A", "text": "特征纹理识别"}, {"letter": "B", "text": "文字识别"}, {"letter": "C", "text": "数字图像处理与识别"}, {"letter": "D", "text": "物体识别"}], "answer": "A", "explanation": "图像识别的发展主要经历文字识别、数字图像处理与识别、物体识别三个阶段，特征纹理只是识别中常用的一种图像特征提取方法，并非独立的发展阶段，因此选A。最易混淆的是C，数字图像处理与识别是承上启下的关键阶段，而非单纯的技术手段。"}, {"id": 49, "section": "人工智能专题", "num": 49, "stem": "下列属于实现无人驾驶所必须具备的技术是（ ）。", "options": [{"letter": "A", "text": "感知系统"}, {"letter": "B", "text": "决策系统"}, {"letter": "C", "text": "执行系统"}, {"letter": "D", "text": "以上都是"}], "answer": "D", "explanation": "无人驾驶是一个“感知—决策—执行”的闭环系统：感知系统通过摄像头、雷达等采集路况，决策系统据此规划路径、判断行驶策略，执行系统再控制转向、油门与刹车，三者缺一不可，因此选D。最容易混淆的是只选感知系统，误以为能“看见”就能自动驾驶，实际上没有决策和执行，车辆根本无法安全行驶。"}, {"id": 50, "section": "人工智能专题", "num": 50, "stem": "下列不属于国内AIGC技术使用工具的是（ ）。", "options": [{"letter": "A", "text": "ChatGPT"}, {"letter": "B", "text": "文心一言"}, {"letter": "C", "text": "SparkDesk"}, {"letter": "D", "text": "通义千问"}], "answer": "A", "explanation": "国内AIGC工具主要指由中国企业研发并面向国内用户提供服务的大模型产品。ChatGPT由美国OpenAI公司开发，不属于国内工具，故选A。最易混淆的是文心一言，它是百度推出的国产大模型，常被误认为国外产品，但实为国内代表性工具。"}, {"id": 51, "section": "人工智能专题", "num": 51, "stem": "在人工智能领域，生物信息识别中用于专注力分析的脑电波是（ ）。", "options": [{"letter": "A", "text": "α波和β波"}, {"letter": "B", "text": "δ波和θ波"}, {"letter": "C", "text": "θ波和β波"}, {"letter": "D", "text": "α波和δ波"}], "answer": "C", "explanation": "专注力分析常用θ波与β波的比值（θ/β）作为指标：θ波增多常与注意力分散、分心有关，β波增强则对应主动思考与集中注意，因此二者组合能有效反映专注程度。最易混淆的是A项，α波主要与放松、闭目静息状态相关，并非专注力的核心指标。"}, {"id": 52, "section": "信息技术基础专题", "num": 1, "stem": "既可作为输入设备，又可作为输出设备的是（）", "options": [{"letter": "A", "text": "打印机"}, {"letter": "B", "text": "键盘"}, {"letter": "C", "text": "磁盘驱动器"}, {"letter": "D", "text": "显示器"}], "answer": "C", "explanation": "输入设备负责向计算机送入数据，输出设备负责把处理结果呈现出来，而存储类设备可双向读写，因而兼具两者功能。磁盘驱动器既能把磁盘数据读入内存，也能把内存数据写入磁盘保存，所以是输入输出两用设备。显示器最容易混淆，它只负责把信息显示出来，属于纯输出设备，不能向计算机输入数据。"}, {"id": 53, "section": "信息技术基础专题", "num": 2, "stem": "计算机的发展趋势是巨型化、微小化、网络化、（）、多媒体化。", "options": [{"letter": "A", "text": "智能化"}, {"letter": "B", "text": "数字化"}, {"letter": "C", "text": "自动化"}, {"letter": "D", "text": "以上都对"}], "answer": "A", "explanation": "计算机发展的五大趋势是巨型化、微型化、网络化、智能化与多媒体化，智能化指计算机模拟人的学习、推理与决策能力，是人工智能发展的必然方向，故选A。最容易误选D，数字化与自动化只是实现智能化的基础与手段，并非并列的五大趋势之一。"}, {"id": 54, "section": "信息技术基础专题", "num": 3, "stem": "在计算机中，用来解释、执行程序中指令的部件是（）", "options": [{"letter": "A", "text": "运算器"}, {"letter": "B", "text": "存储器"}, {"letter": "C", "text": "控制器"}, {"letter": "D", "text": "鼠标器"}], "answer": "C", "explanation": "控制器是计算机的指挥中心，负责从存储器中取出指令并进行译码，然后向各部件发出控制信号，协调其按序执行程序，因此是解释、执行指令的核心部件。最容易混淆的是运算器，它只负责算术与逻辑运算，本身并不负责取指、译码和发出控制命令。"}, {"id": 55, "section": "信息技术基础专题", "num": 4, "stem": "计算机常用的输入设备有（）", "options": [{"letter": "A", "text": "显示器、鼠标器"}, {"letter": "B", "text": "键盘、显示器"}, {"letter": "C", "text": "打印机、绘图仪"}, {"letter": "D", "text": "键盘、鼠标器，扫描仪"}], "answer": "D", "explanation": "输入设备负责把外部信息送入计算机，输出设备则把处理结果呈现出来。键盘、鼠标和扫描仪分别用于输入文字指令、定位操作和图像信息，因此D正确。最易混淆的是A、B中的显示器，它是典型的输出设备，只负责显示结果，不能向计算机输入信息。"}, {"id": 56, "section": "信息技术基础专题", "num": 5, "stem": "微型计算机通常是由（）等几部分组成。", "options": [{"letter": "A", "text": "运算器、控制器、存储器和输入输出设备"}, {"letter": "B", "text": "运算器、外部存储器、控制器和输入输出设备"}, {"letter": "C", "text": "电源、控制器、存储器和输入输出设备"}, {"letter": "D", "text": "运算器、放大器、存储器和输入输出设备"}], "answer": "A", "explanation": "微型计算机遵循冯·诺依曼结构，由运算器、控制器、存储器和输入输出设备五大部件构成，其中运算器与控制器合称中央处理器，负责运算与指挥，存储器负责数据保存，输入输出设备负责人机交互，因此A正确。最易混淆的是B，它把存储器窄化为外部存储器，忽略了内存这一核心组成部分。"}, {"id": 57, "section": "信息技术基础专题", "num": 6, "stem": "目前在下列各种设备中，读取数据快慢的顺序为（）", "options": [{"letter": "A", "text": "软驱、硬驱、内存和光驱"}, {"letter": "B", "text": "软驱、内存、硬驱和光驱"}, {"letter": "C", "text": "内存、硬驱、光驱和软驱"}, {"letter": "D", "text": "光驱、软驱、硬驱和内存"}], "answer": "C", "explanation": "核心是存储层次的速度差异：内存采用半导体电子存取，无需机械寻道，速度最快；硬盘、光驱、软驱均为机械存储，转速与寻道效率依次变差，所以速度依次递减。最容易混淆的是A，它把硬盘排在内存之前，误以为容量大、常用的硬盘更快，实际上硬盘的机械读写远慢于内存。"}, {"id": 58, "section": "信息技术基础专题", "num": 7, "stem": "PC机的更新主要基于（）的变革。", "options": [{"letter": "A", "text": "软件"}, {"letter": "B", "text": "微处理器"}, {"letter": "C", "text": "存储器"}, {"letter": "D", "text": "磁盘的容量"}], "answer": "B", "explanation": "微处理器是PC的核心部件，决定运算速度、指令集与整体性能，历代PC的换代本质上就是CPU架构与制程的升级。软件、存储器和磁盘容量的提升多是围绕CPU性能展开的配套改进，不能作为划分换代的主要依据，尤其不能把更新频繁的软件误认为换代动力。"}, {"id": 59, "section": "信息技术基础专题", "num": 8, "stem": "PC机性能指标中的内存容量一般指的是（）", "options": [{"letter": "A", "text": "RAM+CACHE"}, {"letter": "B", "text": "ROM+CACHE"}, {"letter": "C", "text": "RAM+ROM"}, {"letter": "D", "text": "RAM+ROM+CACHE"}], "answer": "C", "explanation": "内存容量指主存容量，由随机存取存储器RAM和只读存储器ROM共同构成，两者是CPU直接访问的内存体系，决定了可同时处理的数据规模，因此选C。最易混淆的是D，高速缓存Cache虽能加速访问，但属于CPU与主存之间的缓冲，不计入内存容量。"}, {"id": 60, "section": "信息技术基础专题", "num": 9, "stem": "十进制18.8125转换为二进制数的结果是( )。", "options": [{"letter": "A", "text": "10110.1110"}, {"letter": "B", "text": "10010.1101"}, {"letter": "C", "text": "11010.1101"}, {"letter": "D", "text": "10111.1101"}], "answer": "B", "explanation": "十进制转二进制需整数部分除二取余、小数部分乘二取整。18除二取余得10010，0.8125依次乘二取整得1101，合起来即10010.1101，故选B。最易混淆的是A，其整数部分误算为10110，且小数末位也算错。"}, {"id": 61, "section": "信息技术基础专题", "num": 10, "stem": "一台完整的计算机是由（）、存储器、输入设备、输出设备等部件构成。", "options": [{"letter": "A", "text": "中央处理器"}, {"letter": "B", "text": "软盘"}, {"letter": "C", "text": "键盘"}, {"letter": "D", "text": "硬盘"}], "answer": "A", "explanation": "冯·诺依曼结构将计算机划分为运算器、控制器、存储器、输入设备和输出设备五大部件，其中运算器与控制器合称中央处理器，负责执行指令和处理数据，是计算机的核心，所以选A。硬盘只是存储器的一种具体形式，属于存储部件，不能与中央处理器并列，容易混淆。"}, {"id": 62, "section": "信息技术基础专题", "num": 11, "stem": "喷墨打印机是一种（）", "options": [{"letter": "A", "text": "输入设备"}, {"letter": "B", "text": "存储设备"}, {"letter": "C", "text": "输出设备"}, {"letter": "D", "text": "以上都错"}], "answer": "C", "explanation": "计算机设备按数据流向分为输入、输出和存储三类，输出设备负责将计算机处理后的信息呈现给用户。喷墨打印机接收电脑传来的数据并喷墨打印在纸上，属于典型的输出设备。最容易混淆的是输入设备，键盘、鼠标等才是向计算机输入信息的设备，打印机方向正好相反。"}, {"id": 63, "section": "信息技术基础专题", "num": 12, "stem": "用下面（）可将图片输入到计算机中。", "options": [{"letter": "A", "text": "数码照相机"}, {"letter": "B", "text": "绘图仪"}, {"letter": "C", "text": "键盘"}, {"letter": "D", "text": "鼠标"}], "answer": "A", "explanation": "输入设备负责把外部信息转换为计算机能处理的数据，数码照相机通过光学成像和数字化处理直接生成图像文件并传输给计算机，因此属于图像输入设备。最容易混淆的是绘图仪，它看似与图形有关，实为输出设备，是将计算机中的图形打印、绘制到纸张上，方向正好相反。"}, {"id": 64, "section": "信息技术基础专题", "num": 13, "stem": "（）是大写字母锁定键，主要用于连续输入若干大写字母。", "options": [{"letter": "A", "text": "Tab"}, {"letter": "B", "text": "Caps Lock"}, {"letter": "C", "text": "Shift"}, {"letter": "D", "text": "Alt"}], "answer": "B", "explanation": "Caps Lock是键盘上的大小写锁定切换键，按下后进入大写锁定状态，此后输入的字母均为大写，再按一次即可解除，适合长时间保持大写输入的场景。最容易混淆的是Shift，它只在按住期间临时切换大小写，松开即恢复，并不能锁定大写状态。"}, {"id": 65, "section": "信息技术基础专题", "num": 14, "stem": "Windows的目录结构采用的是（ ）", "options": [{"letter": "A", "text": "树形结构"}, {"letter": "B", "text": "线形结构"}, {"letter": "C", "text": "层次结构"}, {"letter": "D", "text": "网状结构"}], "answer": "A", "explanation": "Windows目录以根目录为起点，文件夹逐级包含子文件夹和文件，形成一对多的分支关系，这正是树形结构的核心特征。层次结构虽也描述分层现象，但未点明根节点唯一、分支逐级展开的树形特征，因此不如树形结构准确，容易混淆。"}, {"id": 66, "section": "信息技术基础专题", "num": 15, "stem": "在Internet中的IP地址由（ ）位二进制数组成。", "options": [{"letter": "A", "text": "8"}, {"letter": "B", "text": "16"}, {"letter": "C", "text": "32"}, {"letter": "D", "text": "64"}], "answer": "C", "explanation": "IPv4地址是互联网最常用的地址格式，由32位二进制数构成，通常写成4个十进制数以点分隔，每个数对应8位，因此共4×8=32位。容易混淆的是A选项，8位只是一段地址的长度，而非整个IP地址的长度。"}, {"id": 67, "section": "信息技术基础专题", "num": 16, "stem": "下列打印机中，打印效果最佳的一种是", "options": [{"letter": "A", "text": "点阵打印机"}, {"letter": "B", "text": "激光打印机"}, {"letter": "C", "text": "热敏打印机"}, {"letter": "D", "text": "喷墨打印机"}], "answer": "B", "explanation": "激光打印机通过激光成像使碳粉吸附并高温定影，输出的文字边缘锐利、线条清晰且不易晕染、褪色，因此综合打印质量最高。最易混淆的是喷墨打印机，它色彩表现细腻，但墨水易受纸张和潮湿影响，文字清晰度和保存耐久性通常不如激光打印。"}, {"id": 68, "section": "信息技术基础专题", "num": 17, "stem": "以下使用计算机的不好习惯是（）", "options": [{"letter": "A", "text": "将用户文件建立在所用系统软件的子目录内"}, {"letter": "B", "text": "对重要的数据常做备份"}, {"letter": "C", "text": "关机前退出所有的应用程序"}, {"letter": "D", "text": "使用标准的文件扩展名"}], "answer": "A", "explanation": "良好的文件管理要求用户数据与系统程序分开存放，便于备份、重装与权限管理；把用户文件放在系统软件子目录内，一旦系统重装或软件卸载就容易误删、丢失，也会干扰系统运行，所以是不好习惯。最容易混淆的是关机前退出程序，有人觉得系统会自动关闭而多此一举，其实提前退出才能保存数据、避免文件损坏，是规范操作。"}, {"id": 69, "section": "信息技术基础专题", "num": 18, "stem": "一个完整的计算机系统应包括（）", "options": [{"letter": "A", "text": "主机、键盘和显示器"}, {"letter": "B", "text": "计算机及其外部设备"}, {"letter": "C", "text": "系统硬件和系统软件"}, {"letter": "D", "text": "硬件系统和软件系统"}], "answer": "D", "explanation": "完整的计算机系统由硬件系统与软件系统两大部分组成，二者缺一不可，硬件提供物理基础与运行载体，软件指挥硬件工作并实现各种功能，因此D正确。最易混淆的是C，它把软件系统偷换为系统软件，漏掉了应用软件，表述并不完整。"}, {"id": 70, "section": "信息技术基础专题", "num": 19, "stem": "计算机系统由（ ）系统和（ ）系统两部分组成， 它们之间的关系是（）", "options": [{"letter": "A", "text": "硬件、软件、无关"}, {"letter": "B", "text": "主机、外设、无关"}, {"letter": "C", "text": "硬件、软件、相辅相成"}, {"letter": "D", "text": "主机、软件、相辅相成"}], "answer": "C", "explanation": "计算机系统由硬件与软件两大系统构成，硬件是物质基础，软件是灵魂，二者缺一不可、相辅相成，缺硬件软件无法运行，缺软件硬件只是空壳。最易混淆的是D，主机只是硬件的一部分，不能与软件并列作为系统的两大组成。"}, {"id": 71, "section": "信息技术基础专题", "num": 20, "stem": "下面（）组设备包括：输入设备、输出设备和存储设备。", "options": [{"letter": "A", "text": "显示器、CPU和ROM"}, {"letter": "B", "text": "磁盘、鼠标和键盘"}, {"letter": "C", "text": "鼠标、绘图仪和光盘"}, {"letter": "D", "text": "磁带、打印机和调制解调器"}], "answer": "C", "explanation": "输入设备将外部信息送入计算机，输出设备将处理结果送出，存储设备用于长期保存数据。鼠标属于输入设备，绘图仪可输出图形，光盘用于存储数据，三类齐全，故C正确。最容易混淆的是B，磁盘是存储设备，鼠标和键盘都是输入设备，缺少输出设备。"}, {"id": 72, "section": "信息技术基础专题", "num": 21, "stem": "计算机的应用领域可大致分为三个方面，指出下列答案中正确的是", "options": [{"letter": "A", "text": "计算机辅助教学 专家系统 人工智能"}, {"letter": "B", "text": "工程计算 数据结构 文字处理"}, {"letter": "C", "text": "实时控制 科学计算 数据处理"}, {"letter": "D", "text": "数值处理 人工智能 操作系统"}], "answer": "C", "explanation": "计算机应用按用途可概括为科学计算、数据处理和实时控制三大领域，分别对应数值运算、信息管理和过程控制，因此C正确。最容易混淆的是A，计算机辅助教学、专家系统和人工智能都只是某一领域下的具体应用，不能与三大领域并列。"}, {"id": 73, "section": "信息技术基础专题", "num": 22, "stem": "世界上第一台电子数字计算机于（）诞生在（）", "options": [{"letter": "A", "text": "1946年、法国"}, {"letter": "B", "text": "1946年、美国"}, {"letter": "C", "text": "1946年、英国"}, {"letter": "D", "text": "1946年、德国"}], "answer": "B", "explanation": "ENIAC是第一台通用电子数字计算机，于1946年在美国宾夕法尼亚大学研制成功，标志着现代计算机时代的开端，因此选B。容易混淆的是C：英国虽研制了用于破译密码的“巨人”机，但它并非通用电子数字计算机，且诞生时间也不是1946年。"}, {"id": 74, "section": "信息技术基础专题", "num": 23, "stem": "（）是显示器的一个重要技术指标。", "options": [{"letter": "A", "text": "对比度"}, {"letter": "B", "text": "分辨率"}, {"letter": "C", "text": "亮度"}, {"letter": "D", "text": "尺寸大小"}], "answer": "B", "explanation": "分辨率指显示器横向与纵向像素点的数量，决定画面清晰度和可显示信息量，是衡量显示性能的核心指标，因此选B。对比度、亮度、尺寸也常被提及，但它们属于显示效果或外观参数，并非决定成像精细程度的关键技术指标，其中最易混淆的是对比度，它只反映明暗层次差异，不能代表清晰度。"}, {"id": 75, "section": "信息技术基础专题", "num": 24, "stem": "关于CPU，下面说法不正确的是（）", "options": [{"letter": "A", "text": "CPU是中央处理器的简称"}, {"letter": "B", "text": "CPU可以代替存储器"}, {"letter": "C", "text": "PC机的CPU也称为微处理器"}, {"letter": "D", "text": "CPU是计算机的核心部件"}], "answer": "B", "explanation": "CPU即中央处理器，是计算机执行指令与处理数据的核心部件，PC机中的CPU属于微处理器。CPU虽内置少量寄存器和缓存，可临时高速存取数据，但容量很小且断电即失，无法承担内存与外存的存储职能，所以不能代替存储器。容易混淆的是把缓存当成内存，实际上缓存只是为加速运算服务的临时中转空间。"}, {"id": 76, "section": "信息技术基础专题", "num": 25, "stem": "在PC机中，VGA的含义是（）", "options": [{"letter": "A", "text": "显示器型号"}, {"letter": "B", "text": "机器型号"}, {"letter": "C", "text": "显示标准"}, {"letter": "D", "text": "CPU型号"}], "answer": "C", "explanation": "VGA是IBM于1987年推出的视频图形阵列显示标准，规定了640×480分辨率、256色等显示规范，后成为通用接口与显示模式的代称，因此它属于显示标准而非具体硬件。最易混淆的是A，显示器只是遵循该标准生产的设备，型号由厂商另行命名，不能与标准本身等同。"}, {"id": 77, "section": "信息技术基础专题", "num": 26, "stem": "在PC机上通过键盘输入一段文章时，该段文章首先存放在主机的（）中，如果希望将这段文章长期保存，就应把它以（）形式存储于（）中。", "options": [{"letter": "A", "text": "内存、文件、外存"}, {"letter": "B", "text": "外存、数据、内存"}, {"letter": "C", "text": "内存、字符、外存"}, {"letter": "D", "text": "键盘、文字、打印机"}], "answer": "A", "explanation": "键盘输入的数据需先进入内存供CPU处理，内存断电即失，不能长期保存；长期保存要把数据组织成文件，存入硬盘等外存中，外存断电仍可保留。最易混淆的是C项：字符只是文章的组成单位，不是长期保存的组织形式，只有文件才能作为整体被存取和管理。"}, {"id": 78, "section": "信息技术基础专题", "num": 27, "stem": "一台完整的计算机主要由运算器、控制器、存储器、输入设备（）等部件构成。", "options": [{"letter": "A", "text": "输出设备"}, {"letter": "B", "text": "键盘"}, {"letter": "C", "text": "软件"}, {"letter": "D", "text": "CPU"}], "answer": "A", "explanation": "冯·诺依曼结构把计算机硬件分为运算器、控制器、存储器、输入设备和输出设备五大部件，输入与输出共同负责与外界交换信息，所以空缺处应为输出设备。最容易混淆的是D项，CPU只是运算器与控制器的合称，是五大部件的组成部分，不能与它们并列。"}, {"id": 79, "section": "信息技术基础专题", "num": 28, "stem": "完整的计算机系统由（ ）组成。", "options": [{"letter": "A", "text": "运算器、控制器、存储器、输入设备和输出设备"}, {"letter": "B", "text": "主机和外部设备"}, {"letter": "C", "text": "硬件系统和软件系统"}, {"letter": "D", "text": "主机箱、显示器、键盘、鼠标、打印机"}], "answer": "C", "explanation": "完整的计算机系统是硬件与软件的统一体，硬件提供运算、存储与输入输出的物理基础，软件则指挥硬件工作并实现各种应用，二者缺一不可，因此选C。最容易混淆的是A，它描述的是冯·诺依曼体系结构中硬件系统的五大组成部分，只是硬件层面的划分，不能代表完整的计算机系统。"}, {"id": 80, "section": "信息技术基础专题", "num": 29, "stem": "十进制数27对应的二进制数为（ ）。", "options": [{"letter": "A", "text": "1011"}, {"letter": "B", "text": "1100"}, {"letter": "C", "text": "10111"}, {"letter": "D", "text": "11011"}], "answer": "D", "explanation": "十进制转二进制可用除以2取余倒序排列，或按权展开：27=16+8+2+1，对应2^4、2^3、2^1、2^0位为1，其余为0，故为11011。最易混淆的是C，10111=16+4+2+1=23，它把8误写成4，漏掉了8这一位。"}, {"id": 81, "section": "信息技术基础专题", "num": 30, "stem": "计算机软件一般包括（）", "options": [{"letter": "A", "text": "程序及数据"}, {"letter": "B", "text": "程序及文档"}, {"letter": "C", "text": "文档及数据"}, {"letter": "D", "text": "算法及数据"}], "answer": "B", "explanation": "计算机软件是程序与相关文档的集合，程序是可执行的指令序列，文档则记录设计、说明与维护信息，两者共同构成完整软件，缺一不可。最易混淆的是A，数据是程序运行中处理的对象或结果，属于程序运行的输入输出，而非软件本身的构成要素。"}, {"id": 82, "section": "信息技术基础专题", "num": 31, "stem": "计算机的指令由（）组成。", "options": [{"letter": "A", "text": "操作数与地址码"}, {"letter": "B", "text": "操作码与操作对象"}, {"letter": "C", "text": "操作码与源操作数"}, {"letter": "D", "text": "地址码与目地操作数"}], "answer": "B", "explanation": "计算机指令由操作码和操作对象构成，操作码规定执行何种操作，操作对象则指明操作所针对的数据或其地址。两者配合才能完整表达一条指令的含义。最易混淆的A项没有操作码，操作数与地址码都只涉及数据，无法说明要做什么操作。"}, {"id": 83, "section": "信息技术基础专题", "num": 32, "stem": "要运行一个程序文件，则它必须被装入到（）中。", "options": [{"letter": "A", "text": "RAM"}, {"letter": "B", "text": "ROM"}, {"letter": "C", "text": "CD-ROM"}, {"letter": "D", "text": "EPROM"}], "answer": "A", "explanation": "程序运行时，CPU只能直接访问内存，磁盘上的程序文件需先装入可读写的随机存取存储器RAM中才能执行，断电后其内容会丢失。ROM则是只读存储器，主要固化存放系统启动等固定程序，不能作为程序运行的临时工作区。"}, {"id": 84, "section": "信息技术基础专题", "num": 33, "stem": "发现计算机病毒后，若无法消除的话，则彻底的清除方法是（）", "options": [{"letter": "A", "text": "用查毒软件处理"}, {"letter": "B", "text": "删除磁盘文件"}, {"letter": "C", "text": "用杀毒软件处理"}, {"letter": "D", "text": "格式化磁盘"}], "answer": "D", "explanation": "计算机病毒是寄生在文件或系统中的恶意程序，常规查杀依赖病毒库识别，未知或顽固病毒可能无法彻底清除。格式化磁盘会重建文件系统并清除全部数据，从而连同病毒一并清除，是无法消除时的彻底办法。最易混淆的是用杀毒软件处理，它只能清除已知病毒，无法保证彻底清除顽固病毒。"}, {"id": 85, "section": "信息技术基础专题", "num": 34, "stem": "操作系统是一种（）软件。", "options": [{"letter": "A", "text": "实用"}, {"letter": "B", "text": "应用"}, {"letter": "C", "text": "编辑"}, {"letter": "D", "text": "系统"}], "answer": "D", "explanation": "软件分为系统软件和应用软件两大类，系统软件是管理计算机硬件与软件资源、为应用软件提供运行平台的基础软件。操作系统直接管理内存、进程、文件和设备，是最典型的系统软件，因此选D。最容易混淆的是B，应用软件是运行在操作系统之上、面向具体任务的程序，如办公软件、浏览器等，不能与操作系统本身混为一谈。"}, {"id": 86, "section": "信息技术基础专题", "num": 35, "stem": "Windows从软件归类来看是属于（）", "options": [{"letter": "A", "text": "操作系统"}, {"letter": "B", "text": "应用软件"}, {"letter": "C", "text": "文字处理软件"}, {"letter": "D", "text": "数据库"}], "answer": "A", "explanation": "操作系统是直接管理计算机硬件、为其他软件提供运行环境和资源调度的系统软件，Windows负责进程、内存、文件与设备管理并支撑各类应用运行，因此属于操作系统。最易混淆的是应用软件，它是安装在操作系统之上、面向具体任务的程序，如办公、浏览器等，不能与提供底层平台的系统软件混为一谈。"}, {"id": 87, "section": "信息技术基础专题", "num": 36, "stem": "应用软件是指（）", "options": [{"letter": "A", "text": "所有能够使用的软件"}, {"letter": "B", "text": "能被各应用单位共同使用的某种软件"}, {"letter": "C", "text": "所有微机上都应使用的基本软件"}, {"letter": "D", "text": "专门为某一应用目的而编制的软件"}], "answer": "D", "explanation": "软件按用途分为系统软件与应用软件，前者管理、支撑计算机运行，后者直接服务于用户的具体任务，因此专门为某一应用目的编制的软件才是应用软件。最容易混淆的是C，它描述的是操作系统等基本软件，属于系统软件而非应用软件。"}, {"id": 88, "section": "信息技术基础专题", "num": 37, "stem": "Internet中域名系统将域名地址分为几个级别,一级、二级、三级和各个子级.常见的域名\"com\"代表().", "options": [{"letter": "A", "text": "教育机构"}, {"letter": "B", "text": "政府机构"}, {"letter": "C", "text": "网络机构"}, {"letter": "D", "text": "商业机构"}], "answer": "D", "explanation": "通用顶级域名按注册机构的性质划分，com取自英文commercial商业一词的缩写，专门分配给企业等商业组织使用，所以代表商业机构。容易混淆的是C选项，net才是网络服务提供机构的顶级域名，而com并不表示网络机构本身。"}, {"id": 89, "section": "信息技术基础专题", "num": 38, "stem": "在上网输入地址时,一般要开头写上http,其含义是( )", "options": [{"letter": "A", "text": "一种修饰没有意义"}, {"letter": "B", "text": "表示在中国上网"}, {"letter": "C", "text": "TCP/IP"}, {"letter": "D", "text": "超文本传输协议"}], "answer": "D", "explanation": "HTTP是超文本传输协议的英文缩写，属于应用层协议，用于规定浏览器与服务器之间如何请求和传输网页等超文本资源，因此地址栏开头写它表示按该协议访问。最容易混淆的是C，TCP/IP是一组底层网络协议的总称，负责数据传输与寻址，并非HTTP本身。"}, {"id": 90, "section": "信息技术基础专题", "num": 39, "stem": "以下哪个URL的写法是正确的? ( )", "options": [{"letter": "A", "text": "http://www.mcp.com\\que\\que.html"}, {"letter": "B", "text": "http//www.mcp.com\\que\\que.html"}, {"letter": "C", "text": "http://www.mcp.com/que/que.html"}, {"letter": "D", "text": "http//www.mcp.com/que/que.html"}], "answer": "C", "explanation": "URL由协议、主机和路径组成，标准格式为协议名后加冒号加双斜杠，路径各层级之间用正斜杠分隔，因此C符合规范。最容易混淆的是D，它路径用了正斜杠却漏掉了协议后的冒号，http//不是合法的协议写法。"}, {"id": 91, "section": "信息技术基础专题", "num": 40, "stem": "一般把软件分为两大类（）", "options": [{"letter": "A", "text": "文字处理软件和数据库管理软件"}, {"letter": "B", "text": "操作系统和数据库管理系统"}, {"letter": "C", "text": "程序和数据"}, {"letter": "D", "text": "系统软件和应用软件"}], "answer": "D", "explanation": "软件按功能用途可分为系统软件与应用软件，前者为计算机运行提供基础支撑，如操作系统、编译程序，后者直接面向用户完成具体任务，如办公软件。最易混淆的是C项，程序和数据是软件的组成部分，描述的是软件由什么构成，而非按用途划分的类别。"}, {"id": 92, "section": "信息技术基础专题", "num": 41, "stem": "（）称为完整的计算机软件。", "options": [{"letter": "A", "text": "供大家使用的软件"}, {"letter": "B", "text": "各种可用的程序"}, {"letter": "C", "text": "程序连同有关的说明资料"}, {"letter": "D", "text": "CPU能够执行的所有指令"}], "answer": "C", "explanation": "完整的计算机软件不仅指可运行的程序，还包括与之配套的数据、文档和使用说明等资料，三者共同构成可理解、可维护、可使用的软件系统，因此选C。最容易混淆的是B，它只强调程序本身，忽略了说明资料同样是软件不可缺少的组成部分。"}, {"id": 93, "section": "信息技术基础专题", "num": 42, "stem": "计算机病毒是一种（）", "options": [{"letter": "A", "text": "幻觉"}, {"letter": "B", "text": "程序"}, {"letter": "C", "text": "生物体"}, {"letter": "D", "text": "化学物质"}], "answer": "B", "explanation": "计算机病毒本质上是一段具有自我复制和传播能力的人工编写的代码，属于恶意程序而非自然实体，它需要依附于宿主程序或系统运行并执行破坏、窃取等指令。最容易混淆的是C，病毒只是借用了生物病毒“感染、复制”的比喻，并不具备新陈代谢、自主生命等生物特征。"}, {"id": 94, "section": "信息技术基础专题", "num": 43, "stem": "人们针对某一需要而为计算机编制的指令序列称为（）", "options": [{"letter": "A", "text": "完整的计算机软件"}, {"letter": "B", "text": "程序"}, {"letter": "C", "text": "命令"}, {"letter": "D", "text": "字符串"}], "answer": "B", "explanation": "程序是为解决特定问题，用程序设计语言编写的、能被计算机执行的有序指令集合，强调按步骤完成任务，因此符合题意。最易混淆的是A，完整的计算机软件范围更大，除程序外还包括数据、文档及相关资料，程序只是软件的核心组成部分。"}, {"id": 95, "section": "信息技术基础专题", "num": 44, "stem": "计算机病毒（）", "options": [{"letter": "A", "text": "不影响计算机的运行速度"}, {"letter": "B", "text": "能造成计算机电子器件的永久性失效"}, {"letter": "C", "text": "不影响计算机的运算结果"}, {"letter": "D", "text": "影响程序的执行，破坏用户数据和程序"}], "answer": "D", "explanation": "计算机病毒是能自我复制、潜伏并破坏系统功能的恶意程序，其核心危害在于干扰正常程序执行、篡改或删除数据，因此D正确。最易混淆的是B，病毒属于软件层面的破坏，一般只影响数据与系统运行，不会直接烧毁硬件造成电子器件永久失效。"}, {"id": 96, "section": "信息技术基础专题", "num": 45, "stem": "系统软件和应用软件的相互关系是（）", "options": [{"letter": "A", "text": "前者以后者为基础"}, {"letter": "B", "text": "后者以前者为基础"}, {"letter": "C", "text": "每一类都不以另一类为基础"}, {"letter": "D", "text": "每一类都以另一类为基础"}], "answer": "B", "explanation": "系统软件是管理硬件、为应用提供运行环境的底层支撑，如操作系统；应用软件则面向具体任务，需在其上运行才能发挥作用，因此后者以前者为基础。最容易混淆的是A项，它颠倒了依赖方向，系统软件并不依赖某个具体应用才能存在。"}, {"id": 97, "section": "信息技术基础专题", "num": 46, "stem": "记录在磁盘上的一组相关信息的集合称为（）", "options": [{"letter": "A", "text": "数据"}, {"letter": "B", "text": "外存"}, {"letter": "C", "text": "文件"}, {"letter": "D", "text": "内存"}], "answer": "C", "explanation": "文件是存储在外存上的一组相关信息的集合，是操作系统组织和管理数据的基本单位，磁盘上的数据正是以文件形式存放的，因此选C。最易混淆的是B，外存是磁盘等存储设备本身的统称，指的是硬件载体而非其中的信息集合。"}, {"id": 98, "section": "信息技术基础专题", "num": 47, "stem": "语言编译软件按分类来看是属于（）", "options": [{"letter": "A", "text": "操作系统"}, {"letter": "B", "text": "系统软件"}, {"letter": "C", "text": "应用软件"}, {"letter": "D", "text": "数据库管理系统"}], "answer": "B", "explanation": "系统软件是管理、维护计算机系统并支持应用软件运行的基础软件，语言编译软件将高级语言源程序翻译成机器能执行的代码，属于为编程和系统运行提供支撑的工具，因而归入系统软件而非直接面向用户具体任务的应用软件。操作系统只是系统软件中最核心的一类，编译器并不负责管理硬件资源和进程调度，所以不能选A。"}, {"id": 99, "section": "信息技术基础专题", "num": 48, "stem": "计算机病毒主要是通过（）传播的。", "options": [{"letter": "A", "text": "微生物“病毒体”"}, {"letter": "B", "text": "磁盘和网络"}, {"letter": "C", "text": "人体"}, {"letter": "D", "text": "电源"}], "answer": "B", "explanation": "计算机病毒是人为编写的恶意程序，本质上是代码而非生物体，只能依托存储介质和网络在计算机间复制传播，因此磁盘和网络是最主要的传播途径。最容易混淆的是A项，它把生物病毒与计算机病毒混为一谈，实际上计算机病毒不会感染人体，也无法通过电源传播。"}, {"id": 100, "section": "信息技术基础专题", "num": 50, "stem": "计算机软件一般可分为系统软件和应用软件，其中系统软件的核心是（）", "options": [{"letter": "A", "text": "语言编译程序"}, {"letter": "B", "text": "操作系统"}, {"letter": "C", "text": "数据库管理系统"}, {"letter": "D", "text": "文字处理程序"}], "answer": "B", "explanation": "系统软件是管理计算机硬件与软件资源、为应用软件提供运行平台的基础软件，其核心是操作系统，它直接控制CPU、内存、文件和设备并调度程序运行。语言编译程序虽也属系统软件，但只是将高级语言翻译为机器码的工具，并非系统运行的中枢。"}, {"id": 101, "section": "信息技术基础专题", "num": 51, "stem": "计算机病毒会造成计算机（）的损坏。", "options": [{"letter": "A", "text": "硬件、软件和数据"}, {"letter": "B", "text": "硬件和软件"}, {"letter": "C", "text": "软件和数据"}, {"letter": "D", "text": "硬件和数据"}], "answer": "A", "explanation": "计算机病毒本质上是具有破坏性的恶意程序，可通过篡改、删除文件破坏数据与软件，也能通过改写固件、使硬件超负荷运转等方式造成硬件损坏，因此三者都会受损。最易误选C，因为只看到病毒作用于软件层面，忽略了它对硬件的间接或直接破坏。"}, {"id": 102, "section": "信息技术基础专题", "num": 52, "stem": "CPU的中文意义是（）", "options": [{"letter": "A", "text": "计算机"}, {"letter": "B", "text": "不间断电源"}, {"letter": "C", "text": "算术部件"}, {"letter": "D", "text": "中央处理器"}], "answer": "D", "explanation": "CPU全称Central Processing Unit，即中央处理器，是计算机执行指令、进行运算与控制的核心部件，负责解释执行程序并协调各硬件协同工作，因此D正确。最容易混淆的是C，算术部件即ALU只是CPU内部负责算术与逻辑运算的一部分，不能等同于还包含控制器的整个CPU。"}, {"id": 103, "section": "信息技术基础专题", "num": 53, "stem": "PC机在工作中，电源突然中断，则（）全部不丢失。", "options": [{"letter": "A", "text": "ROM和RAM中的信息"}, {"letter": "B", "text": "RAM中的信息"}, {"letter": "C", "text": "ROM中的信息"}, {"letter": "D", "text": "RAM中的部分信息"}], "answer": "C", "explanation": "ROM属于非易失性存储器，断电后数据仍可长期保存；RAM属于易失性存储器，断电后数据立即丢失，因此只有ROM中的信息全部不丢失。最容易混淆的是A，虽然ROM断电不丢失，但RAM会全部丢失，所以两者不能同时成立。"}, {"id": 104, "section": "信息技术基础专题", "num": 55, "stem": "操作系统是（）的接口。", "options": [{"letter": "A", "text": "用户与软件"}, {"letter": "B", "text": "系统软件与应用软件"}, {"letter": "C", "text": "主机与外设"}, {"letter": "D", "text": "用户与计算机"}], "answer": "D", "explanation": "操作系统是位于用户与计算机硬件之间的系统软件，负责管理硬件资源并为用户提供操作界面，用户通过它发出指令、运行程序，计算机则通过它执行任务，因此它是用户与计算机之间的接口。最容易混淆的是A，用户与软件只是其功能的一个方面，操作系统连接的其实是用户与整台计算机，而非仅与软件。"}, {"id": 105, "section": "信息技术基础专题", "num": 56, "stem": "计算机语言的发展经历了（）、（）和（）几个阶段。", "options": [{"letter": "A", "text": "高级语言、汇编语言和机器语言"}, {"letter": "B", "text": "高级语言、机器语言和汇编语言"}, {"letter": "C", "text": "机器语言、高级语言和汇编语言"}, {"letter": "D", "text": "机器语言、汇编语言和高级语言"}], "answer": "D", "explanation": "计算机语言按抽象程度由低到高演进：最早是直接用二进制指令的机器语言，难以读写；随后出现用助记符代替二进制的汇编语言；最后发展出接近自然语言的高级语言，由编译器翻译执行，编程效率显著提高。因此顺序是机器语言、汇编语言、高级语言。最易混淆的是C项，它把高级语言放在汇编语言之前，颠倒了由低到高的演进方向。"}, {"id": 106, "section": "信息技术基础专题", "num": 57, "stem": "GB2312-80标准规定1个汉字用( ) 字节表示。", "options": [{"letter": "A", "text": "1"}, {"letter": "B", "text": "2"}, {"letter": "C", "text": "3"}, {"letter": "D", "text": "4"}], "answer": "B", "explanation": "GB2312-80采用双字节编码，共收录6763个汉字，一个汉字由两个字节共16位表示，两字节的最高位均为1，以便与单字节的ASCII字符区分，因此正确答案是2字节。最容易混淆的是C，3字节是汉字在UTF-8编码中的常见长度，并非GB2312-80的规定。"}, {"id": 107, "section": "信息技术基础专题", "num": 58, "stem": "将模拟信号转换成（ ）数的过程称为数字化处理。", "options": [{"letter": "A", "text": "二进制"}, {"letter": "B", "text": "十进制"}, {"letter": "C", "text": "十六进制"}, {"letter": "D", "text": "八进制"}], "answer": "A", "explanation": "数字化处理是将连续变化的模拟信号经过采样、量化、编码，转换为离散的数字信号的过程。计算机内部采用二进制，只有0和1两种状态，与电路的高低电平对应，最便于存储、传输和运算，因此数字化结果必须是二进制数。十进制是我们日常习惯的计数方式，但并不适合计算机硬件直接表示，容易误以为数字化就是转成十进制。"}, {"id": 108, "section": "信息技术基础专题", "num": 59, "stem": "防止计算机中信息被窃取的手段不包括（）", "options": [{"letter": "A", "text": "用户识别"}, {"letter": "B", "text": "权限控制"}, {"letter": "C", "text": "数据加密"}, {"letter": "D", "text": "病毒控制"}], "answer": "D", "explanation": "防窃取的核心在于身份认证与访问控制，确保只有授权者能接触和读懂数据。用户识别确认身份，权限控制限定可操作范围，数据加密让被窃数据也无法解读，因此三者都是防窃手段。最容易混淆的是病毒控制，它主要防范病毒感染、破坏与传播，虽能减少部分风险，但并非直接针对窃取的访问控制措施，故不属于本题所指的防窃手段。"}, {"id": 109, "section": "信息技术基础专题", "num": 60, "stem": "下面（）不是计算机高级语言。", "options": [{"letter": "A", "text": "PASCAL"}, {"letter": "B", "text": "CAD"}, {"letter": "C", "text": "BASIC"}, {"letter": "D", "text": "C"}], "answer": "B", "explanation": "高级语言是接近自然语言、需经编译或解释才能执行的程序设计语言，PASCAL、BASIC、C都是典型的代表。CAD是计算机辅助设计的缩写，指利用计算机进行绘图与设计的一类应用软件，并非编程语言。容易误以为带字母组合的CAD也是语言，其实它只是应用系统名称，与编程无关。"}, {"id": 110, "section": "信息技术基础专题", "num": 61, "stem": "近来计算机报刊中常出现的“Python”一词是指（）", "options": [{"letter": "A", "text": "一种计算机语言"}, {"letter": "B", "text": "一种计算机设备"}, {"letter": "C", "text": "一个计算机厂商云集的地方"}, {"letter": "D", "text": "一种新的数据库软件"}], "answer": "A", "explanation": "Python是一种高级通用编程语言，以简洁易读著称，广泛应用于人工智能、数据分析与自动化脚本开发，因此属于语言而非具体产品。最易混淆的是D：它常被用来操作数据库或开发数据库应用，但本身并不是数据库软件，只是实现这些功能的编程工具。"}, {"id": 111, "section": "信息技术基础专题", "num": 62, "stem": "计算机病毒的特点是（）", "options": [{"letter": "A", "text": "传播性、潜伏性和破坏性"}, {"letter": "B", "text": "传播性、潜伏性和易读性"}, {"letter": "C", "text": "潜伏性、破坏性和易读性"}, {"letter": "D", "text": "传播性、潜伏性和安全性"}], "answer": "A", "explanation": "计算机病毒是一段能自我复制并寄生于其他程序中的恶意代码，其核心特征是可借助文件、网络等途径传播，能在宿主体内潜伏一段时间后在特定条件下被触发，进而破坏数据或系统功能，因此A正确。最容易混淆的是B，病毒为逃避检测常对代码进行加密、伪装和隐藏，并不具备易读性。"}, {"id": 112, "section": "信息技术基础专题", "num": 63, "stem": "计算机病毒是（）", "options": [{"letter": "A", "text": "寄生在计算机芯片上的一种细菌"}, {"letter": "B", "text": "对人体有害的传染病毒"}, {"letter": "C", "text": "一种免疫程序"}, {"letter": "D", "text": "一种特殊的能够自我复制的计算机程序"}], "answer": "D", "explanation": "计算机病毒本质上是人为编写的恶意代码，其核心特征是自我复制与传播，并依附于正常程序或文件运行，从而破坏数据或系统功能，因此属于特殊的计算机程序而非生物体。最容易混淆的是A项，它把“病毒”这一比喻当成字面含义，实际上病毒既不是细菌，也不在芯片上寄生。"}, {"id": 113, "section": "信息技术基础专题", "num": 64, "stem": "最基础最重要的系统软件是（）", "options": [{"letter": "A", "text": "数据库管理系统"}, {"letter": "B", "text": "文字处理软件"}, {"letter": "C", "text": "操作系统"}, {"letter": "D", "text": "电子表格软件"}], "answer": "C", "explanation": "操作系统是直接管理计算机硬件与软件资源、为用户和应用提供统一运行环境的系统软件，是其他软件运行的基础，因此最基础也最重要。数据库管理系统属于在操作系统之上运行的应用支撑软件，依赖操作系统调度资源，不能替代操作系统的位置。"}, {"id": 114, "section": "信息技术基础专题", "num": 66, "stem": "操作系统、编译程序和数据库管理系统属于（）", "options": [{"letter": "A", "text": "应用软件"}, {"letter": "B", "text": "系统软件"}, {"letter": "C", "text": "管理软件"}, {"letter": "D", "text": "以上都是"}], "answer": "B", "explanation": "系统软件是支撑计算机运行的基础软件，负责管理硬件资源、提供运行环境和通用服务，三者都属于这一层，因此选B。应用软件最容易混淆，它是面向用户具体任务的软件，如办公、浏览器等，而非底层支撑平台。"}, {"id": 115, "section": "信息技术基础专题", "num": 67, "stem": "管理计算机的硬件设备，并使应用软件能方便、高效地使用这 些设备的是（）", "options": [{"letter": "A", "text": "数据库"}, {"letter": "B", "text": "编译程序"}, {"letter": "C", "text": "编辑软件"}, {"letter": "D", "text": "操作系统"}], "answer": "D", "explanation": "操作系统是计算机系统软件的核心，负责统一管理CPU、内存、外设等硬件资源，并通过系统调用等接口为应用软件提供高效、透明的访问服务，因此选D。最易混淆的是数据库，它管理的是结构化数据的存储、查询与维护，管理对象是数据而非硬件设备本身。"}, {"id": 116, "section": "信息技术基础专题", "num": 68, "stem": "十进制数10.89转换为BCD码的结果是( )。", "options": [{"letter": "A", "text": "1000 0011.1000 1001"}, {"letter": "B", "text": "1001 1100.1000 1001"}, {"letter": "C", "text": "1111 0000.1000 1001"}, {"letter": "D", "text": "0001 0000.1000 1001"}], "answer": "D", "explanation": "BCD码不是把整个数转成二进制，而是把每一位十进制数字分别用4位二进制表示，1对应0001，0对应0000，8对应1000，9对应1001，所以10.89对应0001 0000.1000 1001。最容易混淆的是A，它每组都是合法的BCD码，但表示的是83.89而不是10.89。"}, {"id": 117, "section": "信息技术基础专题", "num": 69, "stem": "计算机以（ ）字节为单位存放1个ASCII码字符。", "options": [{"letter": "A", "text": "1"}, {"letter": "B", "text": "2"}, {"letter": "C", "text": "3"}, {"letter": "D", "text": "4"}], "answer": "A", "explanation": "ASCII码采用7位二进制编码，共可表示128个字符，实际存储时占用1个字节，最高位固定为0，因此选A。最容易混淆的是B，2个字节一般用来存放一个汉字或采用UTF-16编码的字符，而ASCII码中的英文字母和符号只需1个字节，不能混为一谈。"}, {"id": 118, "section": "信息技术基础专题", "num": 70, "stem": "将二进制111101.101转换为BCD编码的结果是（ ）。", "options": [{"letter": "A", "text": "0011 1101.1010 0010"}, {"letter": "B", "text": "0011 1101.1110 1011"}, {"letter": "C", "text": "0110 0001.0110 0010 0101"}, {"letter": "D", "text": "1110 1001.0110 0010 1101"}], "answer": "C", "explanation": "BCD码是8421码，需先把二进制换算成十进制，再把每位十进制数字用四位二进制表示。111101.101等于61.625，6、1、6、2、5依次为0110、0001、0110、0010、0101，故选C。最易混淆的是A，它把二进制直接按四位分组，1101对应13，已超出BCD码0~9的范围。"}, {"id": 119, "section": "信息技术基础专题", "num": 71, "stem": "将BCD码0111 0110.1000 0001转换为十进制数为( )。", "options": [{"letter": "A", "text": "77.80"}, {"letter": "B", "text": "76.81"}, {"letter": "C", "text": "76.80"}, {"letter": "D", "text": "66.81"}], "answer": "B", "explanation": "BCD码的核心是每4位二进制数对应一位十进制数字，逐段翻译而非把整体当作二进制数换算。0111对应7，0110对应6，1000对应8，0001对应1，依次组合起来就是76.81。最容易混淆的是C，整数部分与小数第一位都正确，但0001对应的是1而不是0，忽略末位就会误选。"}, {"id": 120, "section": "信息技术基础专题", "num": 72, "stem": "世界上诞生的第一台电子数字计算机是（）", "options": [{"letter": "A", "text": "EDVAC"}, {"letter": "B", "text": "UNIVAC-I"}, {"letter": "C", "text": "ENIAC"}, {"letter": "D", "text": "EVSAC"}], "answer": "C", "explanation": "ENIAC于1946年在美国宾夕法尼亚大学诞生，是世界上第一台通用电子数字计算机，标志着电子计算机时代的开始。它采用电子管进行运算，运算速度远超此前的机电式计算机。最容易混淆的是EDVAC，它在ENIAC之后研制，是首台采用存储程序原理的计算机，但并非第一台。"}, {"id": 121, "section": "信息技术基础专题", "num": 73, "stem": "世界上第一台电子数字计算机诞生于（）", "options": [{"letter": "A", "text": "1946"}, {"letter": "B", "text": "1949"}, {"letter": "C", "text": "1950"}, {"letter": "D", "text": "1951"}], "answer": "A", "explanation": "ENIAC于1946年在美国宾夕法尼亚大学研制成功，是首台通用电子数字计算机，开启了现代计算机时代，因此选A。1949年常被误认为是首台计算机的诞生年份，但那是第一台存储程序计算机EDSAC问世的时间，并非ENIAC。"}, {"id": 122, "section": "信息技术基础专题", "num": 74, "stem": "第一代计算机称（）计算机。", "options": [{"letter": "A", "text": "晶体管"}, {"letter": "B", "text": "电子管"}, {"letter": "C", "text": "中小规模集成电路"}, {"letter": "D", "text": "大规模或超大规模集成电路"}], "answer": "B", "explanation": "计算机按所用主要电子元件划分代际，第一代以电子管为核心逻辑元件，体积大、功耗高、可靠性低，代表机型为ENIAC。最易混淆的是晶体管，它体积更小、性能更稳定，属于第二代计算机的标志，并非第一代。"}, {"id": 123, "section": "信息技术基础专题", "num": 75, "stem": "目前，制造计算机所使用的逻辑器件主要是（ ）", "options": [{"letter": "A", "text": "大规模集成电路"}, {"letter": "B", "text": "晶体管"}, {"letter": "C", "text": "集成电路"}, {"letter": "D", "text": "大规模或超大规模集成电路"}], "answer": "D", "explanation": "计算机发展按逻辑器件划分为四代，第四代至今以大规模和超大规模集成电路为核心，CPU等芯片正是将数以亿计的晶体管集成在一块硅片上实现的，因此选D。最易混淆的是A，大规模集成电路只涵盖了部分阶段，表述不够全面，未包含超大规模集成电路。"}, {"id": 124, "section": "信息技术基础专题", "num": 76, "stem": "下列哪个选项属于合法的IP地址( )。", "options": [{"letter": "A", "text": "202:144:200:65"}, {"letter": "B", "text": "202.112.146.70"}, {"letter": "C", "text": "202,112,144,70"}, {"letter": "D", "text": "202.112.70"}, {"letter": "E", "text": "202.116.185,70"}, {"letter": "F", "text": "202.116.128.260"}], "answer": "B", "explanation": "IPv4地址由4个用点分隔的十进制数组成，每段取值0～255。B选项四段齐全、分隔符正确且数值均在范围内，因而合法。最易混淆的是F，它形式上与B相近，但末段260超过了255的上限，所以不合法。"}, {"id": 125, "section": "信息技术基础专题", "num": 77, "stem": "计算机中的所有信息都是以（）的形式存储在机器内部的。", "options": [{"letter": "A", "text": "字符"}, {"letter": "B", "text": "二进制编码"}, {"letter": "C", "text": "BCD码"}, {"letter": "D", "text": "ASCII码"}], "answer": "B", "explanation": "计算机硬件只能识别高低电平两种状态，因此所有数据、指令、文字、图像等信息在机器内部都必须统一转换为0和1组成的二进制编码来表示和存储，这是计算机信息表示的基础。最容易混淆的是D项ASCII码，它只是用二进制编码表示英文字符等的一种具体编码规则，并非所有信息的通用存储形式。"}, {"id": 126, "section": "信息技术基础专题", "num": 78, "stem": "在WPS表格公式中,引用同一工作簿内不同工作表的单元格时,工作表名与单元格名之间应使用()分开.", "options": [{"letter": "A", "text": "!"}, {"letter": "B", "text": ":"}, {"letter": "C", "text": ","}, {"letter": "D", "text": ";"}], "answer": "A", "explanation": "跨工作表引用遵循“工作表名!单元格”的固定格式，感叹号用于标识单元格所属的工作表，是Excel与WPS通用的跨表引用符号，因此选A。最容易混淆的是B，冒号是区域运算符，只用于连接同一表内的起止单元格，如A1:B2，不能分隔工作表名与单元格。"}, {"id": 127, "section": "信息技术基础专题", "num": 79, "stem": "下列不是WPS演示文稿视图的是().", "options": [{"letter": "A", "text": "普通视图"}, {"letter": "B", "text": "幻灯片浏览视图"}, {"letter": "C", "text": "备注页视图"}, {"letter": "D", "text": "大纲视图"}], "answer": "D", "explanation": "WPS演示文稿主要有普通视图、幻灯片浏览视图、备注页视图和阅读视图，用于编辑、总览幻灯片和查看备注，因此大纲视图不属于其中。大纲视图是WPS文字的视图，容易因普通视图左侧的大纲窗格而被误认为演示文稿也有该视图。"}, {"id": 128, "section": "信息技术基础专题", "num": 80, "stem": "在WPS演示文稿中,可以创建某些(),在幻灯片放映时单击它们,就可以跳转到特定的幻灯片或运行一个嵌入的演示文稿.", "options": [{"letter": "A", "text": "动作按钮"}, {"letter": "B", "text": "过程"}, {"letter": "C", "text": "替换"}, {"letter": "D", "text": "粘贴"}], "answer": "A", "explanation": "动作按钮是WPS演示中专门用于交互跳转的控件，可为其设置超链接或动作，在放映时单击即可跳转到指定幻灯片、运行其他演示文稿或执行指定操作。过程、替换、粘贴只是编辑流程或操作功能，不具备这种点击触发的跳转能力，其中“过程”最易被误认为与放映流程有关，其实它并非可点击的交互对象。"}, {"id": 129, "section": "信息技术基础专题", "num": 81, "stem": "WPS演示文稿中,关于在幻灯片中插入多媒体内容的说法中错误的是().", "options": [{"letter": "A", "text": "可以插入声音(如掌声)"}, {"letter": "B", "text": "可以插入音乐(如CD乐曲)"}, {"letter": "C", "text": "可以插入影片"}, {"letter": "D", "text": "不可以插入网站中的视频"}], "answer": "D", "explanation": "WPS演示的多媒体插入功能覆盖本地与在线资源，既能插入掌声等音效、CD音乐等音频，也能插入本地影片，还支持通过在线视频功能嵌入网站视频，因此D的说法不成立。最容易混淆的是B，CD乐曲并非只能用光盘播放，在演示中它同样属于可插入的音频类型，只是需要相应的音频文件或链接支持。"}, {"id": 130, "section": "信息技术基础专题", "num": 82, "stem": "以下哪个单词代表电子邮件?( )", "options": [{"letter": "A", "text": "E-mile"}, {"letter": "B", "text": "USENET"}, {"letter": "C", "text": "E-mail"}, {"letter": "D", "text": "Telnet"}], "answer": "C", "explanation": "E-mail是Electronic Mail的缩写，指借助互联网收发信件的服务，人们通过邮箱地址相互传递文字、图片和附件，是互联网最基础、最常见的应用，因此选C。最容易混淆的是E-mile，它把mail错拼成了mile，而mile是长度单位英里，与收发邮件毫无关系，考试时需要仔细辨认字母。"}, {"id": 131, "section": "信息技术基础专题", "num": 83, "stem": "域名服务器上存放着Internet主机的( )。", "options": [{"letter": "A", "text": "域名"}, {"letter": "B", "text": "IP地址"}, {"letter": "C", "text": "电子邮件地址"}, {"letter": "D", "text": "域名和IP地址的对应关系"}], "answer": "D", "explanation": "域名系统（DNS）的核心作用是把便于记忆的域名翻译成计算机识别的IP地址，域名服务器正是保存这种映射关系的数据库，因此选D。最容易混淆的是B，单独的IP地址只是映射结果的一端，没有域名就无法完成解析，服务器存的不是孤立的地址清单。"}, {"id": 132, "section": "信息技术基础专题", "num": 84, "stem": "在计算机中，汉字系统把一个汉字表示为（）", "options": [{"letter": "A", "text": "汉语拼音字母的ASCII代码"}, {"letter": "B", "text": "十进制数的二进制编码"}, {"letter": "C", "text": "按字形笔划设计的二进制吗"}, {"letter": "D", "text": "两个字节的二进制编码"}], "answer": "D", "explanation": "汉字机内码是计算机内部存储、处理汉字时使用的编码，在GB2312等常用编码中一个汉字占两个字节、共16位二进制，因此能表示足够多的汉字，区别于只占一字节的ASCII码。最容易混淆的是A，汉语拼音只是输入法用的输入码，字母本身仍是ASCII码，并不能直接作为汉字的机内表示。"}, {"id": 133, "section": "信息技术基础专题", "num": 85, "stem": "按国内和国际标准，存储一个汉字的内码需要（）字节。", "options": [{"letter": "A", "text": "1"}, {"letter": "B", "text": "2"}, {"letter": "C", "text": "3"}, {"letter": "D", "text": "4"}], "answer": "B", "explanation": "汉字内码采用双字节编码，每个汉字由两个字节表示，最高位均为1，以区别于单字节的ASCII码，因此需要2字节。容易误选C，因为UTF-8中一个汉字确实占3字节，但那是变长编码方式，不是本题所说的内码标准。"}, {"id": 134, "section": "信息技术基础专题", "num": 86, "stem": "在计算机中存储数据的最小单位是（）", "options": [{"letter": "A", "text": "字节"}, {"letter": "B", "text": "位"}, {"letter": "C", "text": "字"}, {"letter": "D", "text": "记录"}], "answer": "A", "explanation": "计算机以字节为基本单位组织和访问内存，一个字节由8位二进制数组成，是存储数据时最小的可寻址单位，因此选字节。最容易混淆的是位，它只是0或1的一个二进制位，是字节的组成部分，而非独立的存储寻址单位。"}, {"id": 135, "section": "信息技术基础专题", "num": 87, "stem": "目前的大多数计算机，就其工作原理而言，基本上采用的是科学 家（）提出的存储程序控制原理。", "options": [{"letter": "A", "text": "比尔.盖茨"}, {"letter": "B", "text": "冯.诺依曼"}, {"letter": "C", "text": "乔治.布尔"}, {"letter": "D", "text": "艾仑.图灵"}], "answer": "B", "explanation": "冯·诺依曼体系结构的核心是存储程序控制：程序和数据都以二进制形式存入存储器，计算机按地址顺序取指、执行，从而自动连续工作，这是现代通用计算机的基本工作原理。图灵最易混淆，他提出图灵机，奠定了可计算性理论，却并非存储程序体系结构的提出者。"}, {"id": 136, "section": "信息技术基础专题", "num": 88, "stem": "下列选项不属于段落缩进方式的是().", "options": [{"letter": "A", "text": "首行缩进"}, {"letter": "B", "text": "悬挂缩进"}, {"letter": "C", "text": "左缩进"}, {"letter": "D", "text": "字符间距"}], "answer": "D", "explanation": "段落缩进是调整段落整体与页边距距离的段落格式，首行缩进、悬挂缩进和左缩进都属于此类，分别控制首行、除首行外各行和段落左侧的缩进量。字符间距则是调整相邻字符间距离的字符格式，与段落位置无关，因此不属于段落缩进。悬挂缩进最易与首行缩进混淆，它是指首行不缩进、其余各行缩进，与首行缩进正好相反。"}, {"id": 137, "section": "信息技术基础专题", "num": 89, "stem": "当要阅读一篇较长的文档时,为其添加( )可以统计文档的页数,便于读者的检索.", "options": [{"letter": "A", "text": "分节符"}, {"letter": "B", "text": "页脚"}, {"letter": "C", "text": "页码"}, {"letter": "D", "text": "分页符"}], "answer": "C", "explanation": "页码是标识文档页面顺序的编号，插入后可自动统计总页数并随内容增减更新，方便定位与检索，因此长文档阅读时应添加页码。最容易混淆的是页脚，它只是页面底部的区域，可放置页码、日期等内容，本身并不具备编号和统计功能。"}, {"id": 138, "section": "信息技术基础专题", "num": 90, "stem": "WPS表格启动后默认的文件类型是().", "options": [{"letter": "A", "text": ".bmp"}, {"letter": "B", "text": ".xlsx"}, {"letter": "C", "text": ".txt"}, {"letter": "D", "text": ".xls"}], "answer": "B", "explanation": "WPS表格是兼容Office的电子表格软件，现行默认保存格式与Excel新版一致，采用基于XML的.xlsx格式，具有更好的兼容性与数据压缩能力。最容易混淆的是.xls，它是Excel 2003及更早版本的旧格式，虽可打开但已不再是默认格式。"}, {"id": 139, "section": "信息技术基础专题", "num": 91, "stem": "在计算机中，一个字节由（）个二进制位组成。", "options": [{"letter": "A", "text": "2"}, {"letter": "B", "text": "4"}, {"letter": "C", "text": "8"}, {"letter": "D", "text": "16"}], "answer": "C", "explanation": "字节是计算机存储和处理信息的基本单位，由8个二进制位构成，每个位只能取0或1，8位组合可表示256种状态，足以编码一个字符，因此成为标准单位。最易混淆的是D选项，16位是两个字节，常用于表示一个字或双字节字符，并非一个字节的位数。"}, {"id": 140, "section": "信息技术基础专题", "num": 92, "stem": "在PC机中，应用最普遍的字符编码是（）", "options": [{"letter": "A", "text": "BCD码"}, {"letter": "B", "text": "ASCII码"}, {"letter": "C", "text": "国标码"}, {"letter": "D", "text": "区位码"}], "answer": "B", "explanation": "ASCII码是美国信息交换标准代码，用7位二进制表示英文字母、数字及常用符号，是PC机中最基础、最通用的字符编码，几乎所有系统都兼容。最易混淆的是国标码，它是我国汉字编码标准，主要用于汉字而非通用字符，因此适用范围远不如ASCII码广泛。"}, {"id": 141, "section": "信息技术基础专题", "num": 93, "stem": "电子数字计算机工作最重要的特征是（ ）", "options": [{"letter": "A", "text": "高速度"}, {"letter": "B", "text": "高精度"}, {"letter": "C", "text": "存储程序和程序控制"}, {"letter": "D", "text": "记忆力强"}], "answer": "C", "explanation": "存储程序和程序控制是冯·诺依曼体系结构的核心，计算机先把程序和数据存入存储器，再由控制器按顺序自动取指、执行，从而实现自动运行和通用计算。高速度只是运算性能的表现，并非决定其工作方式的本质特征。"}, {"id": 142, "section": "信息技术基础专题", "num": 94, "stem": "在\"回收站\"中,存放的只能是( )。", "options": [{"letter": "A", "text": "软盘上被删除的文件夹和文件"}, {"letter": "B", "text": "硬盘和软盘上被删除的文件夹和文件"}, {"letter": "C", "text": "硬盘上被删除的文件夹和文件"}, {"letter": "D", "text": "所有外存储器上被删除的文件夹和文件"}], "answer": "C", "explanation": "回收站是Windows为本地硬盘设置的临时存放区，被删除的文件会先进入其中以便恢复，只有硬盘上的删除操作才走这一机制。软盘、U盘等可移动存储器上的文件删除后是直接永久删除，不经过回收站。最易混淆的是B，它把软盘也算进来，实际上软盘删除的文件不会进入回收站。"}, {"id": 143, "section": "信息技术基础专题", "num": 95, "stem": "在WPS 文字中,选择( )视图,可以使文档的内容按文档的标题层次显示。", "options": [{"letter": "A", "text": "页面视图"}, {"letter": "B", "text": "大纲视图"}, {"letter": "C", "text": "阅读版式视图"}, {"letter": "D", "text": "Web版式视图"}], "answer": "B", "explanation": "大纲视图是专门用于梳理文档结构的视图，它依据标题样式将正文按一级、二级等层级折叠显示，便于整体调整章节顺序与从属关系。页面视图只是模拟打印效果的常规编辑视图，虽能看到完整排版，却无法按标题层级折叠和升降级。"}, {"id": 144, "section": "信息技术基础专题", "num": 96, "stem": "计算机的性能主要取决于（）的性能。", "options": [{"letter": "A", "text": "RAM"}, {"letter": "B", "text": "CPU"}, {"letter": "C", "text": "CRT"}, {"letter": "D", "text": "硬盘"}], "answer": "B", "explanation": "CPU是计算机的核心部件，负责执行指令和处理数据，其主频、核心数与架构直接决定运算速度与整体性能，因此是衡量性能的首要指标。RAM虽影响多任务与数据暂存速度，但只是配合CPU工作的临时存储，容量再大也无法替代CPU的运算能力。"}, {"id": 145, "section": "信息技术基础专题", "num": 97, "stem": "计算机的核心是（）", "options": [{"letter": "A", "text": "存储器"}, {"letter": "B", "text": "运算器"}, {"letter": "C", "text": "控制器"}, {"letter": "D", "text": "CPU"}], "answer": "D", "explanation": "CPU即中央处理器，由运算器和控制器两大部件构成，负责执行指令、进行算术与逻辑运算并统一指挥协调各部件工作，因而是计算机的运算与控制核心。最容易混淆的是控制器，它只是CPU内部负责取指、译码和发出控制信号的部件，是CPU的组成部分而非全部，不能单独代表计算机核心。"}, {"id": 146, "section": "信息技术基础专题", "num": 98, "stem": "在\"记事本\"程序中,无法进行的工作是( ).", "options": [{"letter": "A", "text": "对文字进行简单编辑"}, {"letter": "B", "text": "更换中文输入法"}, {"letter": "C", "text": "实现图文混排"}, {"letter": "D", "text": "进行打印文档的页面设置"}], "answer": "C", "explanation": "记事本是纯文本编辑器，只能处理无格式的文字内容，不支持插入图片、表格等对象，因此无法实现图文混排。最容易误判的是页面设置，记事本虽然功能简单，但文件菜单中仍保留了打印前的页面设置功能，不能因其简陋就认为没有该功能。"}, {"id": 147, "section": "信息技术基础专题", "num": 99, "stem": "以下对\"回收站\"的解释正确的是( ).", "options": [{"letter": "A", "text": "是Windows 7操作系统中的一个组件"}, {"letter": "B", "text": "存在于各逻辑硬盘上的系统文件夹"}, {"letter": "C", "text": "是Windows 7下的一个实用小附件"}, {"letter": "D", "text": "是一个应用程序的快捷方式"}], "answer": "B", "explanation": "回收站并非独立程序，而是每个逻辑分区上名为$Recycle.Bin的隐藏系统文件夹，用于暂存被删除文件以便恢复，因此它随分区存在而非仅属于系统盘。最易混淆的是A，回收站虽由系统管理并在桌面显示，但它不是操作系统本身的组件或附件，只是系统提供的文件暂存机制。"}, {"id": 148, "section": "信息技术基础专题", "num": 100, "stem": "下列存储器中，访问速度最快的是（ ）。", "options": [{"letter": "A", "text": "RAM"}, {"letter": "B", "text": "CD-ROM"}, {"letter": "C", "text": "ROM"}, {"letter": "D", "text": "CACHE"}], "answer": "D", "explanation": "计算机存储体系按速度分层，越靠近CPU的存储器速度越快、容量越小。Cache位于CPU与内存之间，用于暂存CPU最可能马上使用的数据，因此访问速度最快。RAM虽为内存、速度较快，但仍需经总线访问且容量大、速度低于Cache，容易误以为内存就是最快的。"}, {"id": 149, "section": "信息技术基础专题", "num": 101, "stem": "微处理器是微机的核心部件，其性能指标主要取决于（ ）。", "options": [{"letter": "A", "text": "基本指令"}, {"letter": "B", "text": "速度"}, {"letter": "C", "text": "主频"}, {"letter": "D", "text": "字长"}], "answer": "D", "explanation": "微处理器的字长指CPU一次能同时处理的二进制位数，是衡量其数据处理能力、运算精度和寻址范围的核心指标，字长越长性能越强，因此是决定性能的主要因素。主频容易混淆，它只表示CPU每秒的时钟周期数，反映运算速度快慢，但受字长、体系结构和缓存等因素制约，单看主频高低并不能全面决定微处理器的整体性能。"}, {"id": 150, "section": "信息技术基础专题", "num": 102, "stem": "选择多个不连续排列的文件,需要按____按键逐个单击文件名.", "options": [{"letter": "A", "text": "Shift"}, {"letter": "B", "text": "Ctrl"}, {"letter": "C", "text": "Alt"}, {"letter": "D", "text": "Tab"}], "answer": "B", "explanation": "在文件管理器中进行多选时，Ctrl键用于逐个添加不连续的项目，按住它再依次单击即可分别选中，松开后选择仍保留。最容易混淆的是Shift，它用于选中连续范围内的全部文件，而不是逐个挑选不连续文件。"}, {"id": 151, "section": "信息技术基础专题", "num": 103, "stem": "在中文输入和英文输入之间切换所使用的键盘命令是( ).", "options": [{"letter": "A", "text": "Alt+Space"}, {"letter": "B", "text": "Ctrl+Space"}, {"letter": "C", "text": "Ctrl+Shift"}, {"letter": "D", "text": "Shift+Space"}], "answer": "B", "explanation": "中英文输入切换属于输入法状态切换，Ctrl+Space是Windows系统中默认的开启或关闭中文输入法的快捷键，按下后可在中文与英文输入状态间快速切换。最容易混淆的是C项Ctrl+Shift，它用于在已安装的多种输入法之间循环切换，而不是中英文状态切换。"}, {"id": 152, "section": "信息技术基础专题", "num": 104, "stem": "计算机的CPU是指（ ）。", "options": [{"letter": "A", "text": "内存储器和控制器"}, {"letter": "B", "text": "控制器和运算器"}, {"letter": "C", "text": "内存储器和运算器"}, {"letter": "D", "text": "内存储器、控制器和运算器"}], "answer": "B", "explanation": "CPU即中央处理器，是计算机的运算与控制核心，由控制器和运算器两部分组成：控制器负责取指、译码并指挥各部件协调工作，运算器负责算术与逻辑运算。最容易误选D，内存储器虽与CPU配合密切，但属于存储系统而非CPU本身。"}, {"id": 153, "section": "信息技术基础专题", "num": 105, "stem": "具有多媒体功能的PC机上常用CDROM作为外储存器，它是", "options": [{"letter": "A", "text": "只读光盘"}, {"letter": "B", "text": "只读存储器"}, {"letter": "C", "text": "硬盘"}, {"letter": "D", "text": "可擦写光盘"}], "answer": "A", "explanation": "CD-ROM是只读型光盘存储介质，盘片上的数据在生产时一次压制成型，用户只能读取而不能写入、修改或删除，因此属于外存中的只读光盘。最容易混淆的是B项，只读存储器通常指固化在主板上的ROM芯片，属于内存，与作为外存的光盘不是同一类设备。"}, {"id": 154, "section": "信息技术基础专题", "num": 106, "stem": "计算机向用户传递计算、处理结果的设备是（ ）。", "options": [{"letter": "A", "text": "输入设备"}, {"letter": "B", "text": "输出设备"}, {"letter": "C", "text": "存储设备"}, {"letter": "D", "text": "中央处理器"}], "answer": "B", "explanation": "计算机系统按数据流向分为输入、处理、存储与输出，输出设备负责把中央处理器处理后的结果以文字、图像、声音等形式呈现给用户，因此选B。最容易混淆的是输入设备，它的作用恰恰相反，是把外界信息送入计算机，而不是向外传递结果。"}, {"id": 155, "section": "信息技术基础专题", "num": 107, "stem": "鼠标器是一种（ ）。", "options": [{"letter": "A", "text": "输出设备"}, {"letter": "B", "text": "存储器"}, {"letter": "C", "text": "运算控制单元"}, {"letter": "D", "text": "输入设备"}], "answer": "D", "explanation": "计算机硬件按功能分为输入、输出、存储与运算控制等部分，输入设备负责把外部信息传送给计算机进行处理。鼠标通过移动和点击向计算机发出位置与操作指令，属于典型的输入设备。最容易混淆的是输出设备，显示器、打印机等才是把计算机处理结果呈现出来的输出设备，鼠标并不输出信息。"}, {"id": 156, "section": "信息技术基础专题", "num": 108, "stem": "ROM的意思是（ ）。", "options": [{"letter": "A", "text": "软盘存储器"}, {"letter": "B", "text": "硬盘存储器"}, {"letter": "C", "text": "只读存储器"}, {"letter": "D", "text": "随机存储器"}], "answer": "C", "explanation": "ROM是Read Only Memory的缩写，即只读存储器，断电后数据仍能保存，主要用于存放固化程序和启动信息，正常使用时只能读取不能随意改写，因此选C。最容易混淆的是D，随机存储器是RAM的中文名称，可读写且断电后数据丢失，与ROM正好相反。"}, {"id": 157, "section": "信息技术基础专题", "num": 109, "stem": "下列等式中正确的是( ).", "options": [{"letter": "A", "text": "1KB=1024×1024B"}, {"letter": "B", "text": "1MB=1024B"}, {"letter": "C", "text": "1KB=1024MB"}, {"letter": "D", "text": "1MB=1024×1024B"}], "answer": "D", "explanation": "计算机存储单位采用二进制进位，1KB=1024B，1MB=1024KB，因此1MB=1024×1024B，D正确。最易混淆的是A，它把MB的换算误用于KB，实际上1024×1024B等于1MB而非1KB。"}, {"id": 158, "section": "信息技术基础专题", "num": 110, "stem": "一台微机性能的好坏,主要取决于( ).", "options": [{"letter": "A", "text": "内存储器的容量大小"}, {"letter": "B", "text": "CPU的性能"}, {"letter": "C", "text": "显示器的分辨率高低"}, {"letter": "D", "text": "硬盘的容量"}], "answer": "B", "explanation": "微机性能的核心是运算与控制能力，CPU作为中央处理器负责执行指令和处理数据，其主频、核心数与架构直接决定整机速度，因此是决定性因素。内存储器容量大容易被误认为性能关键，它只影响可同时运行的程序数量和数据暂存规模，并不决定运算速度本身。"}, {"id": 159, "section": "信息技术基础专题", "num": 111, "stem": "计算机的内存主要有RAM组成，其中存储的数据在断电后（ ）丢失。", "options": [{"letter": "A", "text": "不会"}, {"letter": "B", "text": "部分"}, {"letter": "C", "text": "完全"}, {"letter": "D", "text": "不一定"}], "answer": "C", "explanation": "RAM即随机存取存储器，是典型的易失性存储器，必须依靠持续供电来保持其中数据，一旦断电，存储的信息便会全部消失，所以应选完全丢失。最容易混淆的是不会丢失，源于把RAM与硬盘、ROM等断电后仍能保存数据的非易失性存储器混为一谈。"}, {"id": 160, "section": "信息技术基础专题", "num": 112, "stem": "（ ）的任务是将计算机外部的信息送入计算机。", "options": [{"letter": "A", "text": "输入设备"}, {"letter": "B", "text": "输出设备"}, {"letter": "C", "text": "软盘"}, {"letter": "D", "text": "电源线"}], "answer": "A", "explanation": "输入设备是计算机与外界交换信息的入口，负责把键盘、鼠标、扫描仪等采集到的文字、图像、声音等外部数据转换为计算机能处理的信号，因此选A。最容易混淆的是输出设备，它的方向正好相反，是把计算机内部的处理结果显示或打印出来给人看，而不是向内输入信息。"}, {"id": 161, "section": "信息技术基础专题", "num": 113, "stem": "字长是CPU的主要性能指标之一,它表示( ).", "options": [{"letter": "A", "text": "CPU一次能处理二进制数据的位数"}, {"letter": "B", "text": "最长的十进制整数的位数"}, {"letter": "C", "text": "最大的有效数字位数"}, {"letter": "D", "text": "计算结果的有效数字长度"}], "answer": "A", "explanation": "字长指CPU一次能并行处理的二进制位数，是衡量CPU数据处理能力与运算速度的重要指标，常见的32位、64位CPU即指此，字长越长，一次运算的数据量越大。B选项最易混淆：CPU内部以二进制运算，字长与十进制位数无关，十进制只是数据的显示形式。"}, {"id": 162, "section": "信息技术基础专题", "num": 114, "stem": "下列各存储器中,存取速度最快的是( ).", "options": [{"letter": "A", "text": "CD-ROM"}, {"letter": "B", "text": "内存储器（RAM）"}, {"letter": "C", "text": "软盘"}, {"letter": "D", "text": "硬盘"}], "answer": "B", "explanation": "存储器按速度分层，CPU可直接访问内存，内存采用半导体电路存取，速度达纳秒级，是程序运行时的直接工作区，因此最快。硬盘等外存虽容量大，但需经I/O传输且多为机械寻道，速度为毫秒级，远慢于内存，不能与内存混为一谈。"}, {"id": 163, "section": "信息技术基础专题", "num": 115, "stem": "计算机硬件能直接识别和执行的只有( ).", "options": [{"letter": "A", "text": "高级语言"}, {"letter": "B", "text": "符号语言"}, {"letter": "C", "text": "汇编语言"}, {"letter": "D", "text": "机器语言"}], "answer": "D", "explanation": "计算机硬件只认由0和1组成的二进制指令，即机器语言，CPU可直接译码执行，无需翻译。高级语言、汇编语言等都需经编译或汇编转换为机器语言才能运行。最易混淆的是汇编语言，它虽用助记符贴近机器，却仍是符号化表示，不能被硬件直接执行。"}, {"id": 164, "section": "信息技术基础专题", "num": 116, "stem": "在表示存储器的容量时，MB的准确含义是（ ）。", "options": [{"letter": "A", "text": "1米"}, {"letter": "B", "text": "1024K字节"}, {"letter": "C", "text": "1024字节"}, {"letter": "D", "text": "1024万字节"}], "answer": "B", "explanation": "计算机存储容量采用二进制换算，1KB等于1024字节，1MB等于1024KB，即1048576字节，因此B正确。最容易混淆的是C，1024字节只是1KB，比1MB小1024倍，混淆了KB与MB的层级。"}, {"id": 165, "section": "信息技术基础专题", "num": 117, "stem": "在计算机中指令主要存放在（ ）中。", "options": [{"letter": "A", "text": "鼠标"}, {"letter": "B", "text": "键盘"}, {"letter": "C", "text": "存储器"}, {"letter": "D", "text": "运算器"}], "answer": "C", "explanation": "计算机采用冯·诺依曼结构，程序和数据以二进制形式统一存放在存储器中，CPU执行时再按地址逐条取出并执行，这就是指令的存放位置。最容易混淆的是运算器，它只负责算术与逻辑运算，本身并不存储程序指令。"}, {"id": 166, "section": "信息技术基础专题", "num": 118, "stem": "将十进制数93转换为二进制数为", "options": [{"letter": "A", "text": "1110111"}, {"letter": "B", "text": "1110101"}, {"letter": "C", "text": "1010111"}, {"letter": "D", "text": "1011101"}], "answer": "D", "explanation": "十进制转二进制可用按权展开：93=64+16+8+4+1，即2^6+2^4+2^3+2^2+2^0，对应位写1、其余写0，得到1011101。最易混淆的A项在32位上多写了1，使结果变为119，超过了93。"}, {"id": 167, "section": "信息技术基础专题", "num": 119, "stem": "在微机中，VGA的含义是", "options": [{"letter": "A", "text": "微机型号"}, {"letter": "B", "text": "键盘型号"}, {"letter": "C", "text": "显示标准"}, {"letter": "D", "text": "显示器型号"}], "answer": "C", "explanation": "VGA是IBM推出的视频图形阵列显示标准，规定了分辨率、色彩数等显示规范，后来也泛指采用该标准的模拟视频接口，因此它属于显示标准而非具体设备。最容易混淆的是D选项，显示器只是遵循VGA标准生产的硬件，标准本身并不等同于某一型号的显示器。"}, {"id": 168, "section": "信息技术基础专题", "num": 120, "stem": "网桥是工作于（ ）的存储转发设备。", "options": [{"letter": "A", "text": "数据链路层"}, {"letter": "B", "text": "网络层"}, {"letter": "C", "text": "传输层"}, {"letter": "D", "text": "物理层"}], "answer": "A", "explanation": "网桥属于数据链路层设备，它依据帧的目的MAC地址进行存储转发与过滤，可隔离冲突域、连接局域网。之所以工作在该层，是因为它处理的是帧而非IP分组，只识别链路层地址。最易混淆的是B，路由器才是网络层设备，依据IP地址转发分组，而非MAC地址。"}, {"id": 169, "section": "信息技术基础专题", "num": 121, "stem": "信道是传输信息的必经之路。根据信道中传输的信号类型来分，物理信道又可分模拟信道和( ) 信道。", "options": [{"letter": "A", "text": "调制"}, {"letter": "B", "text": "解调"}, {"letter": "C", "text": "数字"}, {"letter": "D", "text": "传输"}], "answer": "C", "explanation": "物理信道按所传信号的形态划分：传输连续变化波形的为模拟信道，传输离散脉冲信号的为数字信道，两者对应模拟信号与数字信号的区别，因此选C。调制是把数字信号转换成模拟信号以便传输的处理过程，并非按信号类型划分的信道种类，容易与分类标准混淆。"}, {"id": 170, "section": "信息技术基础专题", "num": 122, "stem": "以下哪个URL的写法是正确的? ( )", "options": [{"letter": "A", "text": "http://www.mcp.com\\que\\que.html"}, {"letter": "B", "text": "http//www.mcp.com\\que\\que.html"}, {"letter": "C", "text": "http://www.mcp.com/que/que.html"}, {"letter": "D", "text": "http//www.mcp.com/que/que.html"}], "answer": "C", "explanation": "URL由协议、主机和路径组成，标准格式为“协议://域名/路径”，其中协议后必须有冒号加双斜杠，路径分隔符只能用正斜杠“/”。因此C符合规范，协议与路径分隔均正确。最易混淆的是A，它保留了正确的协议部分，却把路径分隔符误写为反斜杠“\\”，在URL中无效。"}, {"id": 171, "section": "信息技术基础专题", "num": 123, "stem": "超文本的最基本的含义是什么? ( )", "options": [{"letter": "A", "text": "该文本中包含有图像"}, {"letter": "B", "text": "该文本中包含有声音"}, {"letter": "C", "text": "该文本中包含有二进制字符"}, {"letter": "D", "text": "该文本中包含有链接到其他文本的链接点"}], "answer": "D", "explanation": "超文本的核心在于非线性组织信息，通过超链接将不同文本节点关联起来，读者可按链接跳转而非顺序阅读，因此 D 正确。图像、声音属于多媒体内容，虽可嵌入超文本，却不是其定义特征，容易误把“丰富媒体”等同于“超文本”。"}, {"id": 172, "section": "信息技术基础专题", "num": 124, "stem": "Access提供的数据类型不包括( ).", "options": [{"letter": "A", "text": "文本"}, {"letter": "B", "text": "备注"}, {"letter": "C", "text": "通用"}, {"letter": "D", "text": "日期/时间"}], "answer": "C", "explanation": "Access的字段类型包括文本、备注（长文本）、日期/时间、数字、货币等，用于规范字段可存储的数据形式，其中并没有名为“通用”的类型，因此选C。最容易混淆的是备注，它在新版中改称长文本，但仍是专门存放大段文字的合法类型，并非已被取消。"}, {"id": 173, "section": "信息技术基础专题", "num": 125, "stem": "以下属于 Access数据库子对象的是( ).", "options": [{"letter": "A", "text": "查询"}, {"letter": "B", "text": "表"}, {"letter": "C", "text": "报表"}, {"letter": "D", "text": "以上都是"}], "answer": "D", "explanation": "Access数据库包含表、查询、窗体、报表、宏和模块等对象，其中表存储数据，查询筛选数据，报表呈现数据，三者均为数据库子对象，故选D。易误选B，因表最基础直观，易误以为只有表是子对象，而忽略查询与报表也是独立对象。"}, {"id": 174, "section": "信息技术基础专题", "num": 126, "stem": "Windows 是一种（ ）。", "options": [{"letter": "A", "text": "文件处理系统"}, {"letter": "B", "text": "计算机语言"}, {"letter": "C", "text": "图形化操作系统"}, {"letter": "D", "text": "数据库管理系统"}], "answer": "C", "explanation": "操作系统是管理计算机硬件与软件资源、为用户提供交互界面的系统软件，Windows通过窗口、图标、菜单等图形界面让用户直观操作，因而属于图形化操作系统。最易混淆的是A，文件处理只是操作系统提供的功能之一，不能等同于操作系统本身。"}, {"id": 175, "section": "信息技术基础专题", "num": 127, "stem": "第四代计算机的主要逻辑元件采用的是（ ）", "options": [{"letter": "A", "text": "晶体管"}, {"letter": "B", "text": "小规模集成电路"}, {"letter": "C", "text": "电子管"}, {"letter": "D", "text": "大规模和超大规模集成电路"}], "answer": "D", "explanation": "计算机按逻辑元件划分为四代，第四代始于20世纪70年代初，标志是集成度大幅提高的大规模和超大规模集成电路的广泛应用，使计算机体积更小、速度更快、成本更低。最容易混淆的是小规模集成电路，它属于第三代计算机的标志，而非第四代。"}, {"id": 176, "section": "信息技术基础专题", "num": 128, "stem": "下列叙述中，错误的是（ ）", "options": [{"letter": "A", "text": "把数据从内存传输到硬盘叫写盘"}, {"letter": "B", "text": "把源程序转换为目标程序的过程叫编译"}, {"letter": "C", "text": "应用软件对操作系统没有任何要求"}, {"letter": "D", "text": "计算机内部对数据的传输、存储和处理都使用二进制"}], "answer": "C", "explanation": "应用软件运行在操作系统之上，依赖其提供的文件管理、内存调度、设备驱动等系统服务，不同软件对操作系统类型、版本甚至位数都有明确要求，因此“没有任何要求”是错误的。最易混淆的是A项写盘与读盘的方向：内存到硬盘为写盘，硬盘到内存才是读盘，切勿颠倒。"}, {"id": 177, "section": "信息技术基础专题", "num": 129, "stem": "计算机硬件的五大基本构件包括：运算器、存储器、输入设备、输出设备和（ ）", "options": [{"letter": "A", "text": "显示器"}, {"letter": "B", "text": "控制器"}, {"letter": "C", "text": "磁盘驱动器"}, {"letter": "D", "text": "鼠标器"}], "answer": "B", "explanation": "冯·诺依曼体系结构将计算机硬件划分为运算器、控制器、存储器、输入设备和输出设备五大部分，其中控制器负责指挥协调各部件工作，是计算机的指挥中心，因此选B。最容易混淆的是A，显示器只是输出设备的一种具体表现形式，不能与输出设备并列为独立构件。"}, {"id": 178, "section": "信息技术基础专题", "num": 130, "stem": "通常所说的I/O设备指的是（ ）", "options": [{"letter": "A", "text": "输入输出设备"}, {"letter": "B", "text": "通信设备"}, {"letter": "C", "text": "网络设备"}, {"letter": "D", "text": "控制设备"}], "answer": "A", "explanation": "I/O是Input/Output的缩写，指负责数据输入与输出的外部设备，如键盘、鼠标、显示器和打印机，是人与计算机交换信息的通道，故选A。最易混淆的是B，通信设备主要用于设备间或系统间传输信号，功能更专一，不能等同于广义的输入输出设备。"}, {"id": 179, "section": "信息技术基础专题", "num": 131, "stem": "任何程序都必须加载到( )中才能被CPU执行.", "options": [{"letter": "A", "text": "磁盘"}, {"letter": "B", "text": "硬盘"}, {"letter": "C", "text": "外存"}, {"letter": "D", "text": "内存"}], "answer": "D", "explanation": "CPU只能直接访问内存，这是冯·诺依曼结构下存储层次的基本规则：程序和数据平时保存在外存中，运行时必须先调入内存，CPU再按地址逐条取指执行。最容易混淆的是C，外存只负责长期保存，速度慢且CPU无法直接寻址执行其中的程序。"}, {"id": 180, "section": "信息技术基础专题", "num": 132, "stem": "计算机中数据的表示形式是( ).", "options": [{"letter": "A", "text": "八进制"}, {"letter": "B", "text": "十进制"}, {"letter": "C", "text": "二进制"}, {"letter": "D", "text": "十六进制"}], "answer": "C", "explanation": "计算机内部由晶体管等电子元件构成，只能稳定区分高、低两种电平状态，因此用0和1组成的二进制作为底层数据表示，运算与存储都以此为基础。十进制只是人类日常习惯的计数方式，并非机器内部的表示形式，容易因生活经验而误选。"}, {"id": 181, "section": "信息技术基础专题", "num": 133, "stem": "计算机中1K字节表示的二进制位数是( ).", "options": [{"letter": "A", "text": "1000"}, {"letter": "B", "text": "8×1000"}, {"letter": "C", "text": "1024"}, {"letter": "D", "text": "8×1024"}], "answer": "D", "explanation": "计算机采用二进制计数，存储单位换算以1024为进率，且1字节等于8位二进制数，因此1K字节即1024字节，换算为二进制位数需再乘以8，得到8×1024位。最容易混淆的是C选项，1024只是字节数，没有完成字节到位的一步换算，所以不能直接作为位数。"}, {"id": 182, "section": "信息技术基础专题", "num": 134, "stem": "下列字符中,ASCII码值最小的是( ).", "options": [{"letter": "A", "text": "g"}, {"letter": "B", "text": "A"}, {"letter": "C", "text": "x"}, {"letter": "D", "text": "Z"}], "answer": "B", "explanation": "ASCII码按数字、大写字母、小写字母的顺序递增，其中大写字母A到Z对应65到90，小写字母a到z对应97到122，因此A的65是四个字符中最小的。最容易混淆的是Z，它虽与A同为大写字母，但字母顺序靠后，码值90大于65。"}, {"id": 183, "section": "信息技术基础专题", "num": 135, "stem": "计算机中运算器的主要功能是( ).", "options": [{"letter": "A", "text": "存储各种数据和程序"}, {"letter": "B", "text": "传输各种信息"}, {"letter": "C", "text": "进行算术运算和逻辑运算"}, {"letter": "D", "text": "对系统各部件实行控制"}], "answer": "C", "explanation": "运算器又称算术逻辑单元（ALU），是中央处理器中专门执行数据加工的部件，负责加减乘除等算术运算以及与、或、非等逻辑运算，因此正确答案成立。最容易混淆的是D，'对系统各部件实行控制'是控制器的职责，运算器只负责运算、不负责指挥调度。"}, {"id": 184, "section": "信息技术基础专题", "num": 136, "stem": "显示器显示图像的清晰程度,主要取决于显示器的( ).", "options": [{"letter": "A", "text": "对比度"}, {"letter": "B", "text": "亮度"}, {"letter": "C", "text": "尺寸"}, {"letter": "D", "text": "分辨率"}], "answer": "D", "explanation": "分辨率指屏幕横向与纵向像素点的总数，像素越密、数量越多，单位面积能呈现的细节就越丰富，图像边缘越细腻，因此它是决定清晰程度的关键指标。亮度只影响画面明暗与在强光下的可视性，并不增加细节，容易与清晰度混淆。"}, {"id": 185, "section": "信息技术基础专题", "num": 137, "stem": "下列切换应用程序的方法中，不正确的是（ ）", "options": [{"letter": "A", "text": "单击任务栏上应用程序的图标"}, {"letter": "B", "text": "使用Alt+Tab键"}, {"letter": "C", "text": "使用Alt+Esc键"}, {"letter": "D", "text": "在开始菜单中选择相应的应用程序图标"}], "answer": "D", "explanation": "切换应用程序是指在已运行的程序之间转换焦点，而非重新启动程序。开始菜单用于启动未运行的程序，因此不能算作切换方法。最容易混淆的是Alt+Esc，它虽不显示切换预览，却会按顺序直接切换到下一个已打开窗口，同样是有效的切换方式。"}, {"id": 186, "section": "信息技术基础专题", "num": 138, "stem": "回收站是（ ）", "options": [{"letter": "A", "text": "硬盘上的一个文件"}, {"letter": "B", "text": "硬盘上的一个文件夹"}, {"letter": "C", "text": "软派上的一个文件夹"}, {"letter": "D", "text": "内存中的一个特殊存储区域"}], "answer": "B", "explanation": "回收站是操作系统在硬盘上设置的特殊系统文件夹，用于暂存用户删除的文件，文件并未真正消失，清空前仍可还原，关机后也不会丢失，因此它属于硬盘上的文件夹。最容易混淆的是D项，内存是断电即失的临时工作区，回收站文件是持久保存在硬盘上的，并非内存中的存储区域。"}, {"id": 187, "section": "信息技术基础专题", "num": 139, "stem": "覆盖全球最大的计算机网络是（ ）", "options": [{"letter": "A", "text": "银行网"}, {"letter": "B", "text": "教育网"}, {"letter": "C", "text": "因特网"}, {"letter": "D", "text": "校园网"}], "answer": "C", "explanation": "因特网由全球众多网络通过TCP/IP协议互联而成，覆盖范围最广、接入用户最多，是规模最大的通用计算机网络，因此选C。教育网最容易混淆，它虽跨地区联网，但仍是面向教育科研的行业性网络，并非面向全球公众的通用网络，而银行网和校园网的覆盖范围则更小。"}, {"id": 188, "section": "信息技术基础专题", "num": 140, "stem": "超文本传输协议的英文缩写是（ ）", "options": [{"letter": "A", "text": "WWW"}, {"letter": "B", "text": "HTTP"}, {"letter": "C", "text": "FTP"}, {"letter": "D", "text": "URL"}], "answer": "B", "explanation": "HTTP即超文本传输协议，是浏览器与网站服务器之间传输网页、图片等超文本数据的应用层协议，网页地址以它开头正说明了这一点。最容易混淆的是WWW，它是万维网的简称，指由网页和超链接构成的全球信息系统本身，而不是负责传输的协议。"}, {"id": 189, "section": "信息技术基础专题", "num": 141, "stem": "计算机网络分为广域网主要一句是（ ）", "options": [{"letter": "A", "text": "地理范围"}, {"letter": "B", "text": "连接介质"}, {"letter": "C", "text": "计算机硬件"}, {"letter": "D", "text": "计算机软件"}], "answer": "A", "explanation": "计算机网络按覆盖范围可分为局域网、城域网和广域网，广域网覆盖国家或洲际等大范围区域，因此划分依据是地理范围。连接介质是有线或无线等传输方式，属于网络的物理实现方式而非分类标准，容易与覆盖范围混淆。"}, {"id": 190, "section": "信息技术基础专题", "num": 142, "stem": "在计算机内一切信息存取、传输都是以（ ）形式形成的。", "options": [{"letter": "A", "text": "ASCLL"}, {"letter": "B", "text": "BCD码"}, {"letter": "C", "text": "二进制"}, {"letter": "D", "text": "十六进制"}], "answer": "C", "explanation": "计算机内部由只能区分高低电平的电子元件构成，只能识别0和1两种状态，因此所有数据和指令最终都要统一转换成二进制编码处理。最容易混淆的是十六进制，它只是为方便人阅读而对二进制做的简写表示，并非机器内部真正采用的形式。"}, {"id": 191, "section": "信息技术基础专题", "num": 143, "stem": "Windows是一种（ ）操作系统。", "options": [{"letter": "A", "text": "单用户、单任务"}, {"letter": "B", "text": "单用户、多任务"}, {"letter": "C", "text": "多用户、多任务"}, {"letter": "D", "text": "多用户、单任务"}], "answer": "B", "explanation": "操作系统按同时服务的用户数与任务数分类。Windows面向个人计算机，同一时刻仅供一位用户登录使用，却能同时运行多个程序、通过时间片切换实现多任务，故属单用户、多任务系统。最易混淆的是C：Windows虽有多个账户可切换，但不能让多名用户同时远程登录并行操作，故不算多用户系统。"}, {"id": 192, "section": "信息技术基础专题", "num": 144, "stem": "世界上第一台电子数字计算机取名为（ ）", "options": [{"letter": "A", "text": "UNVAC"}, {"letter": "B", "text": "EDSAC"}, {"letter": "C", "text": "ENIAC"}, {"letter": "D", "text": "EDVAC"}], "answer": "C", "explanation": "ENIAC于1946年在美国宾夕法尼亚大学诞生，是世界上第一台通用电子数字计算机，标志着电子计算机时代的开端。它采用电子管进行运算，虽体积庞大、耗电惊人，但运算速度远超机电式计算机。最易混淆的是EDVAC，它是ENIAC之后冯·诺依曼参与设计的存储程序计算机，并非第一台。"}, {"id": 193, "section": "信息技术基础专题", "num": 145, "stem": "微型计算机中运算器的主要功能是进行（ ）", "options": [{"letter": "A", "text": "算术运算"}, {"letter": "B", "text": "逻辑运算"}, {"letter": "C", "text": "初等函数运算"}, {"letter": "D", "text": "算术和逻辑运算"}], "answer": "D", "explanation": "运算器又称算术逻辑单元（ALU），是CPU中负责执行运算的核心部件，能够对二进制数据进行加减乘除等算术运算，也能进行与、或、非等逻辑运算，因此正确答案是算术和逻辑运算。最容易混淆的是只选算术运算，它只说对了一半，忽略了运算器同样承担与、或、非等逻辑判断运算。"}, {"id": 194, "section": "信息技术基础专题", "num": 146, "stem": "下面中的（ ）不是一种计算机病毒。", "options": [{"letter": "A", "text": "大麻病毒"}, {"letter": "B", "text": "小球病毒"}, {"letter": "C", "text": "衣原体病毒"}, {"letter": "D", "text": "CIH病毒"}], "answer": "C", "explanation": "计算机病毒是能够自我复制并破坏或窃取数据的恶意程序，早期多为引导区病毒和文件型病毒。衣原体是寄生于人体细胞的微生物，属于生物学概念，并非可在计算机中运行的程序，因此不是计算机病毒。大麻病毒与小球病毒名字通俗，却是早期真实存在的引导区病毒，不能因名称生活化就误判为非计算机病毒。"}, {"id": 195, "section": "信息技术基础专题", "num": 147, "stem": "Windows是一种（ ）", "options": [{"letter": "A", "text": "数据库管理系统"}, {"letter": "B", "text": "应用软件"}, {"letter": "C", "text": "系统软件"}, {"letter": "D", "text": "应用支持软件"}], "answer": "C", "explanation": "系统软件管理计算机硬件与软件资源，为应用软件提供运行平台，操作系统是最典型的系统软件。Windows负责管理CPU、内存、文件和设备，并为各类应用提供服务，因此属于系统软件。最容易混淆的是B，应用软件是直接面向用户完成具体任务的程序，如Word、浏览器等，Windows并不直接完成这类任务。"}, {"id": 196, "section": "信息技术基础专题", "num": 148, "stem": "在WPS 文字中，表格的行和列交叉部分，称为（ ）", "options": [{"letter": "A", "text": "单元"}, {"letter": "B", "text": "单元格"}, {"letter": "C", "text": "交叉点"}, {"letter": "D", "text": "单元列"}], "answer": "B", "explanation": "表格是按行列组织数据的结构，行与列相交形成的最小存储与编辑单位就是单元格，每个单元格可独立存放文字、数字等内容。选项A“单元”表述不完整，容易被误认为简称，但规范术语是“单元格”，不能省略“格”字。"}, {"id": 197, "section": "信息技术基础专题", "num": 149, "stem": "计算机网络是计算机技术和（ ）的结合。", "options": [{"letter": "A", "text": "广播技术"}, {"letter": "B", "text": "传播技术"}, {"letter": "C", "text": "通信技术"}, {"letter": "D", "text": "以上皆是"}], "answer": "C", "explanation": "计算机网络的本质是多台计算机通过通信线路与协议互联，实现资源共享与信息交换，因此它正是计算机技术与通信技术融合的产物。传播技术侧重信息的单向扩散与发布，缺乏计算机之间双向互联、协同工作的含义，因而不能作为定义中的另一要素。"}, {"id": 198, "section": "信息技术基础专题", "num": 150, "stem": "局域网中路由器的功能是（ ）", "options": [{"letter": "A", "text": "信息筛选"}, {"letter": "B", "text": "网络通路选择"}, {"letter": "C", "text": "信号转换"}, {"letter": "D", "text": "防止信号衰减"}], "answer": "B", "explanation": "路由器工作在网络层，依据目的IP地址查路由表转发数据包，为数据选择最优传输路径，实现不同网络互联，这是其核心功能。最易混淆的是C，信号转换主要由调制解调器完成，将数字信号与模拟信号相互转换，并非路由器的职责。"}, {"id": 199, "section": "信息技术基础专题", "num": 151, "stem": "下面不是计算机网络传输介质的是（ ）", "options": [{"letter": "A", "text": "双绞线"}, {"letter": "B", "text": "同轴电缆"}, {"letter": "C", "text": "光纤"}, {"letter": "D", "text": "并行传输线"}], "answer": "D", "explanation": "传输介质是承载网络信号的物理通道，有线介质主要包括双绞线、同轴电缆和光纤，前两者用电信号传输，后者用光信号传输。并行传输线描述的是多位数据同时传送的传输方式，不是具体的物理介质，所以不属于传输介质。最容易混淆的是双绞线，它虽然常见于局域网，但本身仍是真实的导线介质。"}, {"id": 200, "section": "信息技术基础专题", "num": 152, "stem": "以下顶级域名中，（ ）代表中国。", "options": [{"letter": "A", "text": "chn"}, {"letter": "B", "text": "cn"}, {"letter": "C", "text": "zg"}, {"letter": "D", "text": "zhg"}], "answer": "B", "explanation": "国家顶级域名采用 ISO 3166-1 的两位字母代码，中国对应的代码是 CN，因此 .cn 是中国的国家顶级域名。容易混淆的是 chn，它是三位字母的国家代码，常用于体育赛事等场合，并非域名体系中的国家顶级域名。"}, {"id": 201, "section": "信息技术基础专题", "num": 153, "stem": "WPS表格的自动填充功能，可以填充（ ）", "options": [{"letter": "A", "text": "相同数据"}, {"letter": "B", "text": "等比数列数据"}, {"letter": "C", "text": "等差数列数据"}, {"letter": "D", "text": "以上都是"}], "answer": "D", "explanation": "自动填充的核心是识别已有数据的规律并按规律延伸。拖动单个单元格可复制相同数据，输入两个等差或等比数列的起始值后拖动，系统会按差值或比值继续生成，因此三类填充都能实现，选D。最易误以为只能复制相同数据，其实只要给出两个有规律的数值，软件就能推断数列关系。"}, {"id": 202, "section": "信息技术基础专题", "num": 154, "stem": "计算机的软件系统可分为（ ）", "options": [{"letter": "A", "text": "程序和数据"}, {"letter": "B", "text": "操作系统和语言处理系统"}, {"letter": "C", "text": "程序、数据和文档"}, {"letter": "D", "text": "系统软件和应用软件"}], "answer": "D", "explanation": "软件系统按功能用途分为系统软件和应用软件，前者如操作系统、语言处理系统等负责管理硬件、支撑运行，后者如办公、绘图软件直接面向用户完成具体任务。最易混淆的是C，程序、数据和文档是软件的组成要素，而非按功能的分类标准。"}, {"id": 203, "section": "信息技术基础专题", "num": 155, "stem": "下列关于存储器的叙述中正确的是（ ）。", "options": [{"letter": "A", "text": "CPU能直接访问存储在内存中的数据，也能直接访问存储在外存中的数据"}, {"letter": "B", "text": "CPU不能直接访问存储在内存中的数据，能直接访问存储在外存中的数据"}, {"letter": "C", "text": "CPU只能直接访问存储在内存中的数据，不能直接访问存储在外存中的数据"}, {"letter": "D", "text": "CPU既不能直接访问存储在内存中的数据，也不能直接访问存储在外存中的数"}], "answer": "C", "explanation": "内存是CPU直接读写的工作区，运算所需的数据和指令必须先调入内存；外存容量大、速度慢，只能长期保存数据，CPU不能直接访问，需经内存中转后才能使用，所以CPU只能直接访问内存。最容易混淆的是A项，它误以为外存也能被CPU直接访问，忽略了内存是CPU与外存之间必经的桥梁。"}, {"id": 204, "section": "信息技术基础专题", "num": 156, "stem": "计算机中所有信息的存储都采用（ ）。", "options": [{"letter": "A", "text": "二进制"}, {"letter": "B", "text": "八进制"}, {"letter": "C", "text": "十进制"}, {"letter": "D", "text": "十六进制"}], "answer": "A", "explanation": "计算机内部用高低电平两种状态表示信息，0和1正好对应通断，电路实现简单、抗干扰强且运算规则简洁，因此一切数据、指令都以二进制存储。十六进制只是为了方便人阅读和书写而对二进制的简写，并非机器真正使用的存储进制。"}, {"id": 205, "section": "信息技术基础专题", "num": 157, "stem": "计算机网络按其覆盖的范围，可划分为（ ）。", "options": [{"letter": "A", "text": "以太网和移动通信网"}, {"letter": "B", "text": "电路交换网和分组交换网"}, {"letter": "C", "text": "局域网、城域网和广域网"}, {"letter": "D", "text": "星形结构、环形结构和总线结构"}], "answer": "C", "explanation": "按覆盖范围分类是计算机网络最基本的划分方式，局域网覆盖建筑物或校园等小范围，城域网覆盖一座城市，广域网则跨越国家或洲际，范围由小到大构成完整体系，因此选C。最易混淆的是D，星形、环形和总线结构是按拓扑结构而非覆盖范围划分的。"}, {"id": 206, "section": "信息技术基础专题", "num": 158, "stem": "下列域名中，表示教育机构的是（ ）。", "options": [{"letter": "A", "text": "ftp.bta.net.cn"}, {"letter": "B", "text": "ftp.cnc.ac.cn"}, {"letter": "C", "text": "www.ioa.ac.cn"}, {"letter": "D", "text": "www.buaa.edu.cn"}], "answer": "D", "explanation": "域名后缀能表明机构的性质与归属，其中.edu专指教育机构，.cn代表中国，所以.edu.cn就是中国的教育机构。北京航空航天大学的域名以.edu.cn结尾，因此D正确。最易混淆的是C，.ac.cn中的ac指科研学术机构而非学校，www.ioa.ac.cn是中国科学院声学研究所的域名。"}, {"id": 207, "section": "信息技术基础专题", "num": 159, "stem": "下列等式中，正确的是（ ）。", "options": [{"letter": "A", "text": "1KB=1024×1024B"}, {"letter": "B", "text": "1MB=1024B"}, {"letter": "C", "text": "1KB=1024MB"}, {"letter": "D", "text": "1MB=1024×1024B"}], "answer": "D", "explanation": "计算机存储单位按1024进位，B、KB、MB依次相邻进率均为1024，因此1KB=1024B，1MB=1024KB=1024×1024B，故D正确。最易混淆的是A，它把MB的换算误套用到KB上，实际上1024×1024B是1MB而非1KB。"}, {"id": 208, "section": "信息技术基础专题", "num": 160, "stem": "计算机病毒可以使整个计算机瘫痪，危害极大。计算机病毒是（ ）。", "options": [{"letter": "A", "text": "一条命令"}, {"letter": "B", "text": "一段特殊的程序"}, {"letter": "C", "text": "一种生物病毒"}, {"letter": "D", "text": "一种芯片"}], "answer": "B", "explanation": "计算机病毒本质上是人为编写的一段具有自我复制、传播和破坏功能的可执行代码，属于特殊程序而非实体物质。它需要依附于宿主程序或系统运行，通过复制扩散造成数据破坏或系统瘫痪，因此选B。最容易混淆的是C，生物病毒是能感染生命体的微生物，而计算机病毒只是代码，不会感染人体，也没有生物结构。"}, {"id": 209, "section": "信息技术基础专题", "num": 161, "stem": "下列设备中，不能作为输出设备的是 （ ）", "options": [{"letter": "A", "text": "鼠标器"}, {"letter": "B", "text": "磁盘驱动器"}, {"letter": "C", "text": "打印机"}, {"letter": "D", "text": "显示器"}], "answer": "A", "explanation": "输入设备负责向计算机传送信息，输出设备负责将处理结果呈现或保存出来。鼠标器只把点击、移动等操作指令输入计算机，无法输出信息，故不能作输出设备。最易混淆的是磁盘驱动器，它既能读出数据，也能把数据写入磁盘保存，属于兼具输入输出功能的设备。"}, {"id": 210, "section": "信息技术基础专题", "num": 162, "stem": "按住（ ）键，拖动文件到回收站，可以真正删除文件而不把它放入回收站。", "options": [{"letter": "A", "text": "ctrl"}, {"letter": "B", "text": "Alt"}, {"letter": "C", "text": "shift"}, {"letter": "D", "text": "空格"}], "answer": "C", "explanation": "删除文件默认会先移入回收站，之后仍可还原；按住 Shift 键操作则会绕过回收站，直接永久删除文件。拖动时配合 Shift，系统不再暂存文件，而是立即执行删除。最容易混淆的是 Ctrl，它常用于复制或多选文件，并不能改变删除的暂存方式。"}, {"id": 211, "section": "信息技术基础专题", "num": 163, "stem": "Internet中人们常用域名表示主机，但在实际处理中，须由（）将域名翻译成IP地址。", "options": [{"letter": "A", "text": "TCP/IP"}, {"letter": "B", "text": "WWW"}, {"letter": "C", "text": "BBS"}, {"letter": "D", "text": "DNS"}], "answer": "D", "explanation": "DNS是域名系统，核心功能就是将便于记忆的域名解析为机器识别的IP地址，相当于互联网的电话簿，因此主机实际通信前必须先查询DNS。TCP/IP容易混淆，它只是负责数据传输与寻址的一组通信协议，并不负责域名翻译。"}, {"id": 212, "section": "信息技术基础专题", "num": 164, "stem": "计算机网络最突出的优点是( )", "options": [{"letter": "A", "text": "运算速度快"}, {"letter": "B", "text": "运算精度高"}, {"letter": "C", "text": "存储容量大"}, {"letter": "D", "text": "资源共享"}], "answer": "D", "explanation": "计算机网络是将多台计算机通过通信线路连接起来、实现互联互通的系统，其核心价值不在于提升单机性能，而在于让分散的硬件、软件和数据资源被多用户共同使用，从而提高利用率、降低成本，因此资源共享是最突出的优点。运算速度快是单台计算机的性能指标，与是否联网无关，容易误以为联网能直接提速。"}, {"id": 213, "section": "信息技术基础专题", "num": 165, "stem": "将源程序转换成目标程序的是（ ）", "options": [{"letter": "A", "text": "调试程序"}, {"letter": "B", "text": "解释程序"}, {"letter": "C", "text": "编译程序"}, {"letter": "D", "text": "编辑程序"}], "answer": "C", "explanation": "编译程序的核心功能是将高级语言编写的源程序整体翻译成机器可执行的目标程序，翻译完成后再执行，效率较高。解释程序最容易混淆，它是逐句翻译并立即执行，不生成独立的目标程序，因此不选。"}, {"id": 214, "section": "信息技术基础专题", "num": 166, "stem": "下列属于计算机在人工智能方面的典型应用是（ ）。", "options": [{"letter": "A", "text": "人机博弈"}, {"letter": "B", "text": "图书管理"}, {"letter": "C", "text": "服装设计"}, {"letter": "D", "text": "视频播放"}], "answer": "A", "explanation": "人工智能的核心是让机器模拟人的感知、推理、学习与决策能力，典型应用包括人机博弈、模式识别、机器翻译和专家系统等。人机博弈中计算机需通过搜索、评估与策略推理自主选择最优走法，正体现了这种智能。图书管理则容易混淆，它只是对图书信息的存储、查询和借还进行处理，属于常规数据处理，并不具备推理与学习能力。"}, {"id": 215, "section": "信息技术基础专题", "num": 167, "stem": "计算思维是运用计算机科学的( )进行问题求解、系统设计、以及人类行为理解等涵盖计算机科学之广度的一系列思维活动。", "options": [{"letter": "A", "text": "基础概念"}, {"letter": "B", "text": "思维方式"}, {"letter": "C", "text": "程序设计原理"}, {"letter": "D", "text": "操作系统原理"}], "answer": "A", "explanation": "计算思维的核心是借用计算机科学的基础概念，如抽象、分解、算法等，来分析与解决问题，而非局限于某一技术领域，因此选A。最易混淆的是B，计算思维本身虽是一种思维方式，但题干强调的是其运用的知识基础而非思维方式本身，故不能选B。"}, {"id": 216, "section": "信息技术基础专题", "num": 168, "stem": "下列有关计算机的描述中，不正确的是（ ）。", "options": [{"letter": "A", "text": "由于计算机智能技术的发展，机器人最终可以代替人类。"}, {"letter": "B", "text": "计算机的使用可以提高工作效率和改善生活质量。"}, {"letter": "C", "text": "计算机按照人们编写的并预先存储好的程序，对输入的数据进行加工处理。"}, {"letter": "D", "text": "计算机是完成信息处理的工具。"}], "answer": "A", "explanation": "计算机的本质是按存储程序工作的信息处理工具，只能执行人预先编写的程序，没有自主意识、情感与创造力，因此再智能的机器人也只是人的延伸，无法最终代替人类。最容易混淆的是C：计算机看似能自主加工数据，实则完全依赖人事先设计好的指令运行，并非自己思考决策。"}, {"id": 217, "section": "信息技术基础专题", "num": 169, "stem": "对计算机发展趋势的叙述，描述不正确的是（ ）。", "options": [{"letter": "A", "text": "容量越来越小"}, {"letter": "B", "text": "体积越来越小"}, {"letter": "C", "text": "精确度越来越高"}, {"letter": "D", "text": "速度越来越快"}], "answer": "A", "explanation": "计算机的发展趋势是体积更小、速度更快、精确度更高，同时存储容量不断扩大。A选项把容量说反了，容量应是越来越大而非越来越小，因此不正确。最容易混淆的是B，体积缩小与容量扩大并不矛盾，集成电路进步使更小的设备能装下更大的存储空间。"}, {"id": 218, "section": "信息技术基础专题", "num": 170, "stem": "利用计算机可以对声音、图形、图像等进行处理，这属于计算机（ ）方面的应用。", "options": [{"letter": "A", "text": "数据处理"}, {"letter": "B", "text": "科学计算"}, {"letter": "C", "text": "生产过程控制"}, {"letter": "D", "text": "嵌入式应用"}], "answer": "A", "explanation": "数据处理是指对文字、声音、图形、图像等非数值型数据进行采集、存储、加工和输出，是计算机最广泛的应用之一，因此声音与图像的处理属于这一范畴。最容易混淆的是科学计算，它主要解决复杂的数值运算与数学建模问题，而非对多媒体信息的加工处理。"}, {"id": 219, "section": "信息技术基础专题", "num": 171, "stem": "冯.诺依曼在总结研制第一台计算机时，提出两个重要的改进是（ ）。", "options": [{"letter": "A", "text": "采用二进制和存储程序控制的概念"}, {"letter": "B", "text": "引入CPU和内存储器的概念"}, {"letter": "C", "text": "采用机器语言和十六进制"}, {"letter": "D", "text": "采用ASCII编码系统"}], "answer": "A", "explanation": "冯·诺依曼结构的核心在于用二进制表示数据与指令，并将程序预先存入存储器由计算机自动按序执行，这使通用计算机成为可能，因此A正确。B最易混淆：CPU与内存储器只是该结构中的部件划分，并非冯·诺依曼当时总结出的两项改进。"}, {"id": 220, "section": "信息技术基础专题", "num": 172, "stem": "世界上第一台电子数字计算机采用的主要逻辑部件是（ ）。", "options": [{"letter": "A", "text": "电子管"}, {"letter": "B", "text": "晶体管"}, {"letter": "C", "text": "继电器"}, {"letter": "D", "text": "光电管"}], "answer": "A", "explanation": "ENIAC于1946年诞生，是第一代计算机的代表，其主要逻辑部件是电子管。电子管通过控制电流的通断来实现逻辑运算，虽然体积大、功耗高，但使计算机首次实现了电子化高速计算。最容易混淆的是晶体管，它是第二代计算机的核心部件，出现时间更晚、体积更小，不能用于ENIAC。"}, {"id": 221, "section": "信息技术基础专题", "num": 173, "stem": "记录在光盘、硬盘、软件中的数据属于（ ）。", "options": [{"letter": "A", "text": "模拟信息"}, {"letter": "B", "text": "仿真信息."}, {"letter": "C", "text": "数字信息"}, {"letter": "D", "text": "广播信息"}], "answer": "C", "explanation": "信息按表现形式可分为模拟信息与数字信息，数字信息以离散的二进制编码存储和传输，具有便于复制、处理和长期保存的特点。这类载体上的数据均以二进制形式记录，因此属于数字信息。最易混淆的是模拟信息，它指用连续变化的物理量表示的信息，如传统磁带声音，与离散编码的数字信息不同。"}, {"id": 222, "section": "信息技术基础专题", "num": 174, "stem": "汉字的拼音输入码属于汉字的（ ）。", "options": [{"letter": "A", "text": "内码"}, {"letter": "B", "text": "外码"}, {"letter": "C", "text": "ASCII码"}, {"letter": "D", "text": "标准码"}], "answer": "B", "explanation": "汉字编码按用途分为内码与外码：内码供计算机内部存储与处理，如GBK、Unicode；外码是供人输入的编码，拼音、五笔输入后需转换为内码才能使用，因此拼音输入码属于外码。最易混淆的是A，内码是机器内部表示而非输入方式，不能把输入时用的拼音当作内码。"}, {"id": 223, "section": "信息技术基础专题", "num": 175, "stem": "计算机中信息存储的最小单位是( )。", "options": [{"letter": "A", "text": "字长"}, {"letter": "B", "text": "字节"}, {"letter": "C", "text": "字"}, {"letter": "D", "text": "二进制位"}], "answer": "D", "explanation": "计算机用二进制表示信息，一个二进制位只能取0或1，是构成所有数据的基本元素，因此是存储的最小单位。字节由8个二进制位组成，是常用的基本存储单位，但并非最小；字和字长则与CPU一次处理的数据宽度有关，层次更高。"}, {"id": 224, "section": "信息技术基础专题", "num": 176, "stem": "在微机中，西文字符所采用的编码是（ ）。", "options": [{"letter": "A", "text": "ASCII码"}, {"letter": "B", "text": "EBCDIC码"}, {"letter": "C", "text": "国标码"}, {"letter": "D", "text": "BCD码"}], "answer": "A", "explanation": "微机处理西文信息采用的标准编码是ASCII码，它以7位二进制表示128个字符，涵盖英文字母、数字和常用标点符号，因而成为微机内部交换英文信息的基础。最容易混淆的是EBCDIC码，它也是西文字符编码，但主要用于IBM大型机系统，并非微机通用标准，所以不能选。"}, {"id": 225, "section": "信息技术基础专题", "num": 177, "stem": "在计算机中，组成一个字节的二进制位位数是（ ）。", "options": [{"letter": "A", "text": "8"}, {"letter": "B", "text": "4"}, {"letter": "C", "text": "2"}, {"letter": "D", "text": "1"}], "answer": "A", "explanation": "字节是计算机存储与数据处理的基本单位，规定由8个二进制位即比特组成，因此一个字节能表示256种不同的状态，答案为8。最容易混淆的是B，4个二进制位只相当于半个字节，通常称为半字节，不能单独作为一个字节使用。"}, {"id": 226, "section": "信息技术基础专题", "num": 178, "stem": "在ASCII码表中，根据码值由小到大的排列顺序是（ ）。", "options": [{"letter": "A", "text": "数字符、大写英文字母、小写英文字母、空格字符"}, {"letter": "B", "text": "空格字符、数字符、小写英文字母、大写英文字母"}, {"letter": "C", "text": "数字符、空格字符、大写英文字母、小写英文字母"}, {"letter": "D", "text": "空格字符、数字符、大写英文字母、小写英文字母"}], "answer": "D", "explanation": "ASCII码按数值大小排列，空格为32最小，数字0-9为48-57居中，大写字母A-Z为65-90，小写字母a-z为97-122最大，因此顺序为空格、数字、大写、小写。最易混淆的是B项，它误以为小写字母比大写字母小，实际上同一字母小写码值比大写大32。"}, {"id": 227, "section": "信息技术基础专题", "num": 179, "stem": "下列两个二进制数进行算术加运算，100001+111=（ ）。", "options": [{"letter": "A", "text": "101010"}, {"letter": "B", "text": "100101"}, {"letter": "C", "text": "101000"}, {"letter": "D", "text": "101110"}], "answer": "C", "explanation": "二进制加法遵循逢二进一的规则，须右对齐、从低位逐位相加，低位的1加1会产生连续进位。100001对应十进制33，111对应7，两数相加得40，换算成二进制是101000，所以选C。最容易混淆的A项错在连续进位时从右数第二位处理不当，多算了2，得到101010。"}, {"id": 228, "section": "信息技术基础专题", "num": 180, "stem": "根据数制的基本概念，下列各进制的整数中，值最小的一个是（ ）。", "options": [{"letter": "A", "text": "十六进制数10"}, {"letter": "B", "text": "二进制数10"}, {"letter": "C", "text": "十进制数10"}, {"letter": "D", "text": "八进制数10"}], "answer": "B", "explanation": "同一数字串“10”在不同进制下代表的值等于进制数本身，即1×进制+0，因此进制越小数值越小。二进制10换算为十进制是2，八进制10是8，十进制10是10，十六进制10是16，所以二进制10最小。最容易混淆的是十六进制10，有人误以为它就是10，实际上它是16，是四个数中最大的。"}, {"id": 229, "section": "信息技术基础专题", "num": 181, "stem": "在科学计算时，经常会遇到“溢出”，这是指（ ）。", "options": [{"letter": "A", "text": "数值超出了机器的位所表示的范围"}, {"letter": "B", "text": "数值超出了内存容量"}, {"letter": "C", "text": "数值超出了变量的表示范围"}, {"letter": "D", "text": "计算机出故障了"}], "answer": "A", "explanation": "溢出源于计算机用有限位数的二进制表示数值，超出该位宽能表示的最大值或最小值时结果便无法正确存储，因而发生溢出。选项C最容易混淆：变量的表示范围本身由其数据类型对应的机器位数决定，并非溢出的直接定义，溢出强调的是数值对位宽的超越。"}, {"id": 230, "section": "信息技术基础专题", "num": 182, "stem": "计算机发展的方向是巨型化、微型化、网络化、智能化。其中\"巨型化\"是指（ ）。", "options": [{"letter": "A", "text": "功能更强、运算速度更高、存储容量更大"}, {"letter": "B", "text": "体积大"}, {"letter": "C", "text": "重量重"}, {"letter": "D", "text": "外部设备更多"}], "answer": "A", "explanation": "巨型化并非指物理尺寸变大，而是性能维度的提升，面向气象预报、核模拟等超算需求，追求更强的运算能力、更大的存储和更高的处理速度，因此A正确。最容易混淆的是B，体积大只是早期巨型机的表象，如今超算通过集成化反而更紧凑，不能以体积大小来定义巨型化。"}, {"id": 231, "section": "信息技术基础专题", "num": 183, "stem": "利用计算机对指纹进行识别、对图像和声音进行处理所属的应用领域是（ ）。", "options": [{"letter": "A", "text": "科学计算"}, {"letter": "B", "text": "辅助设计"}, {"letter": "C", "text": "信息处理"}, {"letter": "D", "text": "自动控制"}], "answer": "C", "explanation": "信息处理是指对文字、图像、声音等非数值型数据进行采集、存储、加工与分析。这类应用以感知数据为对象，目的在于提取和利用信息而非进行数值运算，因此属于信息处理。最易混淆的是科学计算，它主要解决数学建模与数值求解等高精度计算问题，与处理感知数据有本质区别。"}, {"id": 232, "section": "信息技术基础专题", "num": 184, "stem": "记录在一般录音录像机的磁带、录像带上的信息属于（ ）。", "options": [{"letter": "A", "text": "数字信息"}, {"letter": "B", "text": "模拟信息"}, {"letter": "C", "text": "仿真信息"}, {"letter": "D", "text": "广播信息"}], "answer": "B", "explanation": "模拟信息指以连续变化的物理量直接表示原信号的信息，磁带、录像带通过磁性强弱的连续变化记录声音和图像，未经过离散化与二进制编码，因此属于模拟信息。最容易与之混淆的是数字信息，它要求信号先被采样量化为离散的0和1，如光盘、U盘中的数据，而非磁带的连续磁信号。"}, {"id": 233, "section": "信息技术基础专题", "num": 185, "stem": "目前，被人们称为3C的技术是指（ ）。", "options": [{"letter": "A", "text": "微电子技术、通信技术和计算机技术"}, {"letter": "B", "text": "信息基础技术、信息系统技术和信息应用技术"}, {"letter": "C", "text": "通信技术、计算机技术和控制技术"}, {"letter": "D", "text": "微电子技术、光电子技术和计算机技术"}], "answer": "C", "explanation": "3C指信息技术的三大支柱，分别是通信技术、计算机技术和控制技术，三者首字母均为C，分别承担信息的传输、处理与调控，共同支撑现代信息系统运行。最容易混淆的是A项，它用微电子技术替换了控制技术，微电子技术虽是计算机与通信的重要基础，却不属于3C的范畴。"}, {"id": 234, "section": "信息技术基础专题", "num": 186, "stem": "1GB的准确值是（ ）。", "options": [{"letter": "A", "text": "1000×1000 KB"}, {"letter": "B", "text": "1024×1024 Bytes"}, {"letter": "C", "text": "1024 MB"}, {"letter": "D", "text": "1024 KB"}], "answer": "C", "explanation": "计算机存储容量采用二进制换算，1KB=1024B，1MB=1024KB，1GB=1024MB，因此C正确。最易混淆的是A，它用十进制的1000换算，是硬盘厂商的标称方式，不是计算机内部的准确二进制换算。"}, {"id": 235, "section": "信息技术基础专题", "num": 187, "stem": "第四代计算机的逻辑器件，采用的是（ ）。", "options": [{"letter": "A", "text": "大规模、超大规模集成电路"}, {"letter": "B", "text": "晶体管"}, {"letter": "C", "text": "中、小规模集成电路"}, {"letter": "D", "text": "微处理器集成电路"}], "answer": "A", "explanation": "计算机按逻辑器件划分代际：第一代电子管，第二代晶体管，第三代中、小规模集成电路，第四代则采用大规模、超大规模集成电路，因此A正确。最易混淆的是D，微处理器是第四代的典型代表和应用成果，但它属于大规模集成电路的一种，并非划分代际所用的逻辑器件类别名称。"}, {"id": 236, "section": "信息技术基础专题", "num": 188, "stem": "将十六进制数1ABH转换为十进制数是（ ）。", "options": [{"letter": "A", "text": "112"}, {"letter": "B", "text": "272"}, {"letter": "C", "text": "273"}, {"letter": "D", "text": "427"}], "answer": "D", "explanation": "十六进制采用逢十六进一的计数方式，每一位上的数字都要乘以该位的位权再相加，A代表10、B代表11，因此1×16²+10×16+11×16⁰=256+160+11=427。最容易错选C项273，它是把A、B都误当作1，按111展开得到256+16+1的结果，完全忽略了字母在十六进制中对应的数值。"}, {"id": 237, "section": "信息技术基础专题", "num": 189, "stem": "在计算机中，二维码阅读器属于（ ）。", "options": [{"letter": "A", "text": "输出设备"}, {"letter": "B", "text": "存储设备"}, {"letter": "C", "text": "输入设备"}, {"letter": "D", "text": "计算设备"}], "answer": "C", "explanation": "计算机设备按数据流向分为输入、输出、存储与处理等类型，输入设备负责把外部信息采集并转换成计算机可识别的数据。二维码阅读器通过扫描光学图案获取编码信息并传入主机，正是向计算机输入数据，因此属于输入设备。最容易混淆的是输出设备，它是将计算机处理结果呈现给外部，如显示器、打印机，与采集外部信息的作用正好相反。"}, {"id": 238, "section": "信息技术基础专题", "num": 190, "stem": "计算机的软件系统包括（ ）。", "options": [{"letter": "A", "text": "程序、数据与文档"}, {"letter": "B", "text": "操作系统与语言处理程序"}, {"letter": "C", "text": "程序与数据"}, {"letter": "D", "text": "系统软件与应用软件"}], "answer": "D", "explanation": "按功能和用途，软件系统分为系统软件与应用软件两大类，前者管理硬件、提供运行平台，如操作系统、语言处理程序，后者面向具体应用需求，如办公软件、浏览器。A项“程序、数据与文档”是软件的构成要素而非分类，容易混淆。"}, {"id": 239, "section": "信息技术基础专题", "num": 191, "stem": "组成计算机CPU的两大部件是（ ）。", "options": [{"letter": "A", "text": "控制器和内存"}, {"letter": "B", "text": "运算器和内存"}, {"letter": "C", "text": "控制器和寄存器"}, {"letter": "D", "text": "运算器和控制器"}], "answer": "D", "explanation": "CPU是计算机的运算和控制核心，由运算器和控制器两大部件构成：运算器负责算术与逻辑运算，控制器负责取指令、译码并指挥各部件协调工作。最容易混淆的是C，寄存器只是CPU内部暂存数据、地址的高速小容量单元，并非与二者并列的大部件。"}, {"id": 240, "section": "信息技术基础专题", "num": 192, "stem": "若用户正在计算机上编辑某个文件，这时突然停电，则全部丢失的是（ ）。", "options": [{"letter": "A", "text": "硬盘中的文件"}, {"letter": "B", "text": "ROM中的信息"}, {"letter": "C", "text": "RAM中的信息"}, {"letter": "D", "text": "ROM和RAM中的信息"}], "answer": "C", "explanation": "RAM是随机存取存储器，具有易失性，断电后其中暂存的未保存编辑内容会立即消失，而硬盘属于外存、ROM属于只读存储器，两者断电后数据都能长期保留，因此只有RAM中的信息会全部丢失。最容易混淆的是A，硬盘只是保存已写入的文件，未保存的编辑数据并不在硬盘中，停电并不会导致硬盘原有文件丢失。"}, {"id": 241, "section": "信息技术基础专题", "num": 193, "stem": "指挥、协调计算机工作的设备是（ ）。", "options": [{"letter": "A", "text": "控制器"}, {"letter": "B", "text": "输入设备"}, {"letter": "C", "text": "输出设备"}, {"letter": "D", "text": "存储器"}], "answer": "A", "explanation": "控制器是计算机的指挥中心，负责发出控制信号、协调运算器、存储器和输入输出设备按指令有序工作，因此它是全机工作的调度者。最容易混淆的是存储器，它只负责保存程序和数据，并不参与指挥和协调各部件的运行。"}, {"id": 242, "section": "信息技术基础专题", "num": 194, "stem": "CPU主要技术性能指标有（ ）。", "options": [{"letter": "A", "text": "可靠性和精度"}, {"letter": "B", "text": "耗电量和效率"}, {"letter": "C", "text": "冷却效率"}, {"letter": "D", "text": "字长、主频和运算速度"}], "answer": "D", "explanation": "CPU的核心性能取决于一次能处理的数据位数、时钟频率高低和单位时间内的运算次数，字长越长、主频越高、运算速度越快，处理能力越强，所以选D。最容易误选A，可靠性和精度属于整机质量评价范畴，并非CPU特有的主要技术性能指标。"}, {"id": 243, "section": "信息技术基础专题", "num": 195, "stem": "任何程序都必须加载到（ ）中才能被CPU执行。", "options": [{"letter": "A", "text": "外存"}, {"letter": "B", "text": "内存"}, {"letter": "C", "text": "硬盘"}, {"letter": "D", "text": "磁盘"}], "answer": "B", "explanation": "CPU只能直接访问内存，程序运行时需先从外存调入内存，由CPU按地址取指执行，因此内存是程序执行的直接场所。最易混淆的是硬盘，它属于外存，只负责长期保存程序和数据，断电后仍存在，但不能被CPU直接访问执行。"}, {"id": 244, "section": "信息技术基础专题", "num": 196, "stem": "下列叙述中，正确的是（ ）。", "options": [{"letter": "A", "text": "用高级程序语言编写的程序称为源程序"}, {"letter": "B", "text": "计算机能直接识别并执行用汇编语言编写的程序"}, {"letter": "C", "text": "机器语言编写的程序执行效率最低"}, {"letter": "D", "text": "高级语言编写的程序的可移植性最差"}], "answer": "A", "explanation": "高级语言编写的、未经编译的程序就是源程序，必须翻译成机器语言后才能被计算机执行，因此A正确。计算机只能直接识别二进制机器语言，汇编语言仍需汇编程序翻译成机器码，所以B最易误选。"}, {"id": 245, "section": "信息技术基础专题", "num": 197, "stem": "被称作\"裸机\"的计算机是指（ ）。", "options": [{"letter": "A", "text": "没有硬盘的微机"}, {"letter": "B", "text": "大型机器的终端机"}, {"letter": "C", "text": "没安装任何软件的微机"}, {"letter": "D", "text": "没安装外部设备的微机"}], "answer": "C", "explanation": "裸机指仅有硬件、尚未安装任何软件的计算机系统，此时只有机器语言能被识别，无法直接运行应用软件，需先装操作系统等系统软件才能使用。最易混淆的是A：没有硬盘只是缺少一种存储硬件，仍可通过其他方式启动或运行软件，并非裸机。"}, {"id": 246, "section": "信息技术基础专题", "num": 198, "stem": "在计算机系统中，控制和管理各种资源、有效地组织多道程序运行的系统软件称为（ ）。", "options": [{"letter": "A", "text": "操作系统"}, {"letter": "B", "text": "文件系统"}, {"letter": "C", "text": "网络管理系统"}, {"letter": "D", "text": "数据库管理系统"}], "answer": "A", "explanation": "操作系统是计算机系统的核心系统软件，负责统一管理CPU、内存、外部设备等硬件与软件资源，并通过进程调度实现多任务并发执行，因此符合题意。文件系统最容易混淆，它只是操作系统中负责文件存储与管理的一部分功能，不能代替操作系统管理全部资源。"}, {"id": 247, "section": "信息技术基础专题", "num": 199, "stem": "下面列出的软件中，缺少（ ）计算机系统难以工作。", "options": [{"letter": "A", "text": "编辑程序"}, {"letter": "B", "text": "应用程序"}, {"letter": "C", "text": "翻译程序"}, {"letter": "D", "text": "操作系统"}], "answer": "D", "explanation": "操作系统是管理硬件与软件资源、为用户提供接口的系统软件，是计算机正常运行的基础平台，没有它硬件无法被有效调度、其他软件也无从启动。应用程序只是完成具体任务的软件，缺了它计算机仍能运行，只是功能受限，容易误以为常用软件不可或缺。"}, {"id": 248, "section": "信息技术基础专题", "num": 200, "stem": "操作系统的基本类型有（ ）。", "options": [{"letter": "A", "text": "实时操作系统、分时操作系统和多任务系统"}, {"letter": "B", "text": "批处理系统、分时系统和实时系统"}, {"letter": "C", "text": "单用户系统、多任务系统及分时系统"}, {"letter": "D", "text": "实时系统、分时系统和多用户系统"}], "answer": "B", "explanation": "按作业处理方式与响应时间，操作系统基本类型分为批处理、分时和实时三类：批处理成批自动运行追求吞吐量，分时轮流共享CPU追求交互响应，实时则要求在限定时间内完成任务。B完整覆盖了这一经典三分法。最易混淆的是A，它把多任务这一并发能力误当作基本类型，混淆了按处理方式分类与按功能特征描述的区别。"}, {"id": 249, "section": "信息技术基础专题", "num": 201, "stem": "文件服务器具有分时系统文件管理的全部功能，能够为用户提供完善的数据、文件和（ ）。", "options": [{"letter": "A", "text": "目录服务"}, {"letter": "B", "text": "视频传输服务"}, {"letter": "C", "text": "数据库服务"}, {"letter": "D", "text": "交换式网络服务"}], "answer": "A", "explanation": "文件服务器的核心职责是集中管理文件系统，其服务层次为数据、文件与目录：目录服务负责文件命名、组织、检索与访问控制，是文件管理不可或缺的部分。数据库服务由数据库服务器提供，侧重结构化数据的查询与事务管理，文件服务器只负责文件的存储与共享，并不提供数据库服务。"}, {"id": 250, "section": "信息技术基础专题", "num": 202, "stem": "在Windows系统中，要选定多个连续的文件或文件夹，应按住（ ）。", "options": [{"letter": "A", "text": "Alt键"}, {"letter": "B", "text": "Ctrl键"}, {"letter": "C", "text": "Shift键"}, {"letter": "D", "text": "Tab键"}], "answer": "C", "explanation": "连续选定依靠范围选择：先单击首个对象，再按住Shift单击末尾对象，系统会自动选中两者之间的全部内容，因此Shift适用于连续区域。最容易混淆的是Ctrl，它是逐个点选不连续对象的方式，不能一次框定连续区间，用它选连续文件会很低效。"}, {"id": 251, "section": "信息技术基础专题", "num": 203, "stem": "文件的类型可以根据（ ）来识别。", "options": [{"letter": "A", "text": "文件的扩展名"}, {"letter": "B", "text": "文件的大小"}, {"letter": "C", "text": "文件的用途"}, {"letter": "D", "text": "文件的存放位置"}], "answer": "A", "explanation": "文件扩展名是文件名中圆点后的后缀，如 .docx、.jpg、.mp4，操作系统和应用软件正是据此判断文件格式并选择打开方式，因此它是识别文件类型的直接依据。最容易混淆的是 C，文件的用途只是使用意图，同一用途可用多种格式的文件实现，无法据此准确识别类型。"}, {"id": 252, "section": "信息技术基础专题", "num": 204, "stem": "允许多个用户以交互方式使用计算机的操作系统称为（ ）。", "options": [{"letter": "A", "text": "批处理操作系统"}, {"letter": "B", "text": "分时操作系统"}, {"letter": "C", "text": "DOS操作系统"}, {"letter": "D", "text": "个人计算机操作系统"}], "answer": "B", "explanation": "分时操作系统的核心是时间片轮转：它将CPU时间切成很短的时间片，轮流分配给多个联机用户，使每个人都感觉在独占使用计算机，从而实现多用户交互。批处理操作系统最易混淆，它侧重作业成批自动处理、提高吞吐量，用户不能在运行中交互干预。"}, {"id": 253, "section": "信息技术基础专题", "num": 205, "stem": "操作系统是对计算机硬件、软件进行（ ）的系统软件。", "options": [{"letter": "A", "text": "编译和链接"}, {"letter": "B", "text": "输入和输出"}, {"letter": "C", "text": "汇编和执行"}, {"letter": "D", "text": "管理和控制"}], "answer": "D", "explanation": "操作系统的本质是管理者而非执行具体任务的工具，它统一调度CPU、内存、外设等硬件资源，并管理文件、进程与用户程序的运行，从而为上层应用提供有序、安全的运行环境。输入和输出只是它众多管理职能中的一部分，不能概括其全部作用。"}, {"id": 254, "section": "信息技术基础专题", "num": 206, "stem": "在Windows“资源管理器”窗口中，要整理C盘的碎片，应选择磁盘“属性”对话框中的（ ）选项卡。", "options": [{"letter": "A", "text": "共享"}, {"letter": "B", "text": "整理"}, {"letter": "C", "text": "常规"}, {"letter": "D", "text": "工具"}], "answer": "D", "explanation": "磁盘碎片整理属于系统维护功能而非磁盘本身的属性设置，系统将其与查错、备份等维护操作集中放在磁盘属性的“工具”选项卡中，因此选D。“整理”只是该选项卡下具体功能按钮的名称，并非选项卡本身，容易因名称相近而误选。"}, {"id": 255, "section": "信息技术基础专题", "num": 207, "stem": "计算机能够直接执行的程序是（ ）。", "options": [{"letter": "A", "text": "源程序"}, {"letter": "B", "text": "汇编语言程序"}, {"letter": "C", "text": "可执行文件"}, {"letter": "D", "text": "命令文件"}], "answer": "C", "explanation": "计算机CPU只能识别由0和1组成的机器语言指令，可执行文件正是经过编译、链接后生成的机器代码文件，操作系统加载后可由CPU直接执行。汇编语言程序最易混淆，它虽与机器指令一一对应，但使用助记符书写，仍需经汇编程序翻译成机器代码后才能运行。"}, {"id": 256, "section": "信息技术基础专题", "num": 208, "stem": "C、C++、Java可归类为（ ）语言。", "options": [{"letter": "A", "text": "高级"}, {"letter": "B", "text": "机器"}, {"letter": "C", "text": "符号"}, {"letter": "D", "text": "自然"}], "answer": "A", "explanation": "高级语言是接近人类自然语言、与具体机器无关的编程语言，需经编译或解释才能执行。C、C++、Java都使用英文单词和数学符号表达逻辑，抽象程度高、跨平台性强，因此属于高级语言。最易混淆的是机器语言，它是二进制代码、直接由硬件执行，而高级语言需要翻译成机器语言才能运行。"}, {"id": 257, "section": "信息技术基础专题", "num": 209, "stem": "（ ）是一种使用几何图形描述程序逻辑关系的程序设计方法。", "options": [{"letter": "A", "text": "数据流图"}, {"letter": "B", "text": "流程图"}, {"letter": "C", "text": "饼图"}, {"letter": "D", "text": "柱形图"}], "answer": "B", "explanation": "流程图是程序设计中用矩形表示处理、菱形表示判断、箭头表示执行方向等几何图形，直观呈现程序的执行顺序、分支与循环等逻辑关系，因此符合题意。最容易混淆的是数据流图，它描述的是数据在系统各部分之间的流动与变换，而非程序内部的控制流程。"}, {"id": 258, "section": "信息技术基础专题", "num": 210, "stem": "结构化程序设计中的三种基本程序结构是指（ ）。", "options": [{"letter": "A", "text": "转移结构、选择结构、分支结构"}, {"letter": "B", "text": "顺序结构、转移结构、分支结构"}, {"letter": "C", "text": "顺序结构、选择结构、循环结构"}, {"letter": "D", "text": "顺序结构、转移结构、循环结构"}], "answer": "C", "explanation": "结构化程序设计认为任何程序都可由三种基本结构组合而成：顺序结构按语句先后依次执行，选择结构根据条件决定执行哪一分支，循环结构在条件满足时重复执行某段代码，三者足以表达所有逻辑，因此选C。最易混淆的是D，它把无条件跳转的转移结构误当作基本结构，转移会破坏程序的清晰结构，应尽量避免。"}, {"id": 259, "section": "信息技术基础专题", "num": 211, "stem": "高级语言程序设计过程是（ ）。", "options": [{"letter": "A", "text": "问题分析，算法确定，代码设计"}, {"letter": "B", "text": "问题分析，代码设计，算法确定"}, {"letter": "C", "text": "算法确定，问题分析，代码设计"}, {"letter": "D", "text": "算法确定，代码设计，问题分析"}], "answer": "A", "explanation": "高级语言程序设计遵循先分析问题、再设计算法、最后编写代码的逻辑顺序。首先要明确待解决的问题及其输入输出，在此基础上确定解决问题的步骤和方法，即算法，之后才能将其翻译为具体的程序代码。最容易混淆的是B选项，它把代码设计放在算法确定之前，颠倒了先有思路再有实现的顺序。"}, {"id": 260, "section": "信息技术基础专题", "num": 212, "stem": "（ ）负担全网的数据传输和通信处理工作。", "options": [{"letter": "A", "text": "通信子网"}, {"letter": "B", "text": "计算机"}, {"letter": "C", "text": "资源子网"}, {"letter": "D", "text": "网卡"}], "answer": "A", "explanation": "计算机网络按功能分为通信子网和资源子网，前者由传输介质、交换设备等构成，专门负责全网数据的传输、交换与通信处理，是网络的通信骨架。最易混淆的是资源子网，它由主机、服务器等构成，主要负责数据处理与资源共享，而非传输。"}, {"id": 261, "section": "信息技术基础专题", "num": 213, "stem": "Internet最初创建的目的是（ ）。", "options": [{"letter": "A", "text": "政治服务"}, {"letter": "B", "text": "经济服务"}, {"letter": "C", "text": "军事服务"}, {"letter": "D", "text": "教育服务"}], "answer": "C", "explanation": "互联网的前身是美国国防部高级研究计划局于1969年建立的ARPANET，旨在构建去中心化的军事通信网络，即使部分节点被摧毁仍能保持指挥通信，因此其最初目的是军事服务。教育服务最易混淆，ARPANET后来才接入大学用于学术交流，那是应用扩展而非创建初衷。"}, {"id": 262, "section": "信息技术基础专题", "num": 214, "stem": "Internet的工作方式是（ ）。", "options": [{"letter": "A", "text": "多用户"}, {"letter": "B", "text": "网络资源共享"}, {"letter": "C", "text": "通信协议"}, {"letter": "D", "text": "客户机/服务器"}], "answer": "D", "explanation": "因特网采用客户机/服务器模式，客户机主动发出请求，服务器集中提供存储、计算与服务响应，双方分工协作完成网络交互，这是其基本运行架构。通信协议如TCP/IP只是保障双方规范对话的规则，并非工作方式本身，最容易误选。"}, {"id": 263, "section": "信息技术基础专题", "num": 215, "stem": "因特网上用户最多、使用最广的服务是（ ）。", "options": [{"letter": "A", "text": "Telnet"}, {"letter": "B", "text": "FTP"}, {"letter": "C", "text": "News"}, {"letter": "D", "text": "WWW"}], "answer": "D", "explanation": "WWW是建立在超文本传输协议之上的分布式信息服务，它通过浏览器整合文字、图片、视频等资源，门槛低、覆盖广，因而成为因特网最主流的应用。FTP虽常用于文件传输，但功能单一、受众局限，仅是WWW生态中的辅助服务，不能与之等量齐观。"}, {"id": 264, "section": "信息技术基础专题", "num": 216, "stem": "计算机网络技术包含的两个主要技术是计算机技术和（ ）。", "options": [{"letter": "A", "text": "通信技术"}, {"letter": "B", "text": "微电子技术"}, {"letter": "C", "text": "数据处理技术"}, {"letter": "D", "text": "自动化技术"}], "answer": "A", "explanation": "计算机网络是计算机技术与通信技术相结合的产物，前者负责数据的处理、存储与应用，后者负责数据的传输与交换，二者缺一不可，因此答案为通信技术。微电子技术容易混淆，它是支撑计算机硬件发展的基础技术，属于计算机技术的底层支撑而非与之并列的网络构成要素。"}, {"id": 265, "section": "信息技术基础专题", "num": 217, "stem": "IP地址127.0.0.1属于特殊的（ ）。", "options": [{"letter": "A", "text": "广播地址"}, {"letter": "B", "text": "本地链路地址"}, {"letter": "C", "text": "回环地址"}, {"letter": "D", "text": "网络地址"}], "answer": "C", "explanation": "127.0.0.1是IPv4中保留的回环地址，也称localhost，数据包发往它时不会离开本机，而是由本机协议栈直接回送，用于本地服务测试和开发调试。最容易混淆的是本地链路地址，它指169.254.0.0/16网段，用于设备无法获取IP时自动配置的临时地址，与回环地址用途完全不同。"}, {"id": 266, "section": "信息技术基础专题", "num": 218, "stem": "要在Web浏览器中查看某一公司的主页，必须知道（ ）。", "options": [{"letter": "A", "text": "该公司的WWW地址"}, {"letter": "B", "text": "该公司的电子邮件地址"}, {"letter": "C", "text": "该公司所在的省市"}, {"letter": "D", "text": "该公司的邮政编码"}], "answer": "A", "explanation": "浏览网页的核心是统一资源定位符URL，浏览器正是依据WWW地址在互联网上定位并请求对应的服务器资源，因此知道网址才能打开主页。电子邮件地址最容易混淆，它用于收发邮件的身份标识，不能被浏览器解析为网页访问路径。"}, {"id": 267, "section": "信息技术基础专题", "num": 219, "stem": "传播计算机病毒的媒介有（ ）。", "options": [{"letter": "A", "text": "双绞线"}, {"letter": "B", "text": "同轴电缆"}, {"letter": "C", "text": "光纤"}, {"letter": "D", "text": "U盘"}], "answer": "D", "explanation": "计算机病毒需依附可存储、可读写的文件或介质才能复制传播，U盘属于可移动存储介质，插入电脑后病毒可随文件自动运行或复制，因此能成为传播媒介。最容易混淆的是双绞线，它与同轴电缆、光纤一样只是传输信号的物理信道，本身不存储文件，因而不会携带病毒。"}, {"id": 268, "section": "信息技术基础专题", "num": 220, "stem": "（ ）是在企业内部网与外部网之间检查网络服务请求分组是否合法，网络中传送的数据是否会对网络安全构成威胁的设备。", "options": [{"letter": "A", "text": "防火墙"}, {"letter": "B", "text": "路由器"}, {"letter": "C", "text": "交换机"}, {"letter": "D", "text": "网桥"}], "answer": "A", "explanation": "防火墙是部署在内外网边界的网络安全设备，依据预设安全策略对进出的数据包进行检查与过滤，拦截非法请求和可能带来威胁的流量，从而保护内部网络。路由器最容易混淆，它主要负责在不同网络间寻址并转发数据、选择传输路径，并不承担安全检测与拦截职责。"}, {"id": 269, "section": "信息技术基础专题", "num": 221, "stem": "以下不属于计算机病毒防治策略的是（ ）。", "options": [{"letter": "A", "text": "确认您手头常备一张真正“干净”的引导盘"}, {"letter": "B", "text": "及时、可靠升级反病毒产品"}, {"letter": "C", "text": "新购置的计算机软件也要进行病"}, {"letter": "D", "text": "整理磁盘"}], "answer": "D", "explanation": "计算机病毒防治的核心在于切断传播途径并及时发现、清除病毒，例如使用干净引导盘、升级反病毒软件和对新软件进行检查。整理磁盘只是磁盘维护与优化操作，能够提高读写效率。将其误认为杀毒手段是常见混淆，它并不能清除或预防病毒，因此不属于防治策略。"}, {"id": 270, "section": "信息技术基础专题", "num": 222, "stem": "计算机黑客是指（ ）。", "options": [{"letter": "A", "text": "能自动产生计算机病毒的一种设备"}, {"letter": "B", "text": "非法窃取计算机网络系统密码，从而进入计算机网络的人"}, {"letter": "C", "text": "专门盗窃计算机及计算机网络系统设备的人"}, {"letter": "D", "text": "非法编制的、专门用于破坏网络系统的计算机病毒"}], "answer": "B", "explanation": "黑客的核心特征是“人”而非工具或程序，指未经授权非法侵入他人计算机系统的人员，窃取密码只是其进入系统的常见手段，因此B正确。最易混淆的是D，它描述的是计算机病毒，属于黑客可能使用的破坏性程序本身，二者主体完全不同。"}, {"id": 271, "section": "信息技术基础专题", "num": 223, "stem": "下列文件格式中，属于视频文件的是（ ）。", "options": [{"letter": "A", "text": "BMP"}, {"letter": "B", "text": "WAV"}, {"letter": "C", "text": "AVI"}, {"letter": "D", "text": "JPG"}], "answer": "C", "explanation": "AVI是常见的视频容器格式，能够同时封装视频画面和伴随的音频数据，因此属于视频文件。BMP和JPG都是静态图像格式，前者是无压缩位图，后者是常用压缩照片格式，均不含动态影像。最容易混淆的是WAV，它只是无损音频格式，只能保存声音，没有视频画面。"}, {"id": 272, "section": "信息技术基础专题", "num": 224, "stem": "下列选项中属于多媒体输入设备的是（ ）。", "options": [{"letter": "A", "text": "显示器"}, {"letter": "B", "text": "扫描仪"}, {"letter": "C", "text": "打印机"}, {"letter": "D", "text": "音箱"}], "answer": "B", "explanation": "多媒体输入设备负责将外部的文字、图像、声音等信息采集并转换成计算机可处理的数据，扫描仪能把纸质图文转化为数字图像，正属于此类。显示器、打印机和音箱都是输出设备，只负责呈现或打印处理结果而非采集信息，其中显示器最易被误认，它只是显示已处理的信息，并不输入数据。"}, {"id": 273, "section": "信息技术基础专题", "num": 225, "stem": "所谓媒体是指（ ）。", "options": [{"letter": "A", "text": "表示和传播信息的载体"}, {"letter": "B", "text": "各种信息的编码"}, {"letter": "C", "text": "计算机的输入和输出信息"}, {"letter": "D", "text": "计算机屏幕显示的信息"}], "answer": "A", "explanation": "媒体是信息表示与传播的载体，涵盖文字、图像、音频、视频等多种形式，其本质在于承载并传递信息，而非信息本身。选项B最易混淆，编码只是将信息转换为可存储、传输的符号形式，属于媒体信息的处理方式，不是媒体的定义。"}, {"id": 274, "section": "信息技术基础专题", "num": 226, "stem": "JPEG是用于（ ）的编码标准。", "options": [{"letter": "A", "text": "音频和视频图像"}, {"letter": "B", "text": "视频图像"}, {"letter": "C", "text": "音频标准"}, {"letter": "D", "text": "静态图像"}], "answer": "D", "explanation": "JPEG由联合图像专家组制定，是针对静态图像的有损压缩标准，利用离散余弦变换去除空间冗余，在保证视觉质量的同时大幅减小文件体积，因此广泛用于照片存储与传输。最易混淆的是B，视频图像的编码标准是MPEG而非JPEG，JPEG只处理单帧静态画面。"}, {"id": 275, "section": "信息技术基础专题", "num": 227, "stem": "下列资料中，（ ）不是多媒体素材。", "options": [{"letter": "A", "text": "光盘"}, {"letter": "B", "text": "波形、声音"}, {"letter": "C", "text": "文本、数据"}, {"letter": "D", "text": "图形、图像、视频、动画"}], "answer": "A", "explanation": "多媒体素材是指承载信息的各类内容元素，包括文本、图形、图像、音频、视频和动画等，它们是可直接呈现或加工的内容本身。光盘只是存储这些内容的物理载体，属于存储介质而非素材。最易混淆的是文本、数据，常被误认为只是普通资料，但文本是多媒体最基本的构成元素之一。"}, {"id": 276, "section": "信息技术基础专题", "num": 228, "stem": "家用电脑既能听音乐又能看影视节目，这是利用计算机的（ ）。", "options": [{"letter": "A", "text": "自动控制技术"}, {"letter": "B", "text": "多媒体技术"}, {"letter": "C", "text": "文字处理技术"}, {"letter": "D", "text": "电脑作曲技术"}], "answer": "B", "explanation": "多媒体技术是指能够综合处理文字、声音、图像、视频等多种媒体信息并实现交互呈现的技术，电脑同时播放音乐与影视正是其典型应用。自动控制技术最易混淆，它主要用于对设备、生产过程的自动调节与运行控制，而非媒体内容的综合处理与播放。"}, {"id": 277, "section": "信息技术基础专题", "num": 229, "stem": "对同一幅照片采用以下格式存储时，占用存储空间最大的格式是（ ）。", "options": [{"letter": "A", "text": ".BMP"}, {"letter": "B", "text": ".JPG"}, {"letter": "C", "text": ".TIF"}, {"letter": "D", "text": ".GIF"}], "answer": "A", "explanation": "BMP采用无压缩存储，逐像素保存完整的颜色信息，几乎不丢弃任何数据，因此同幅照片的文件最大。JPG采用有损压缩，会丢弃人眼不敏感的高频细节来大幅减小体积。最易混淆的是TIF，它虽也常为无损格式，但支持LZW等压缩，实际文件通常比BMP小。"}, {"id": 278, "section": "信息技术基础专题", "num": 230, "stem": "下列媒体中，不属于时变媒体的是（ ）。", "options": [{"letter": "A", "text": "图形"}, {"letter": "B", "text": "动画"}, {"letter": "C", "text": "音频"}, {"letter": "D", "text": "视频"}], "answer": "A", "explanation": "时变媒体指内容随时间变化、需按时间顺序呈现的媒体，音频、视频、动画都随时间播放变化。图形是由点、线、面等几何要素构成的静态图像，不随时间改变，因此属于时不变媒体。最易混淆的是动画，它看似由静态画面组成，但帧与帧连续变化、依赖时间播放，所以是时变媒体。"}, {"id": 279, "section": "信息技术基础专题", "num": 231, "stem": "多媒体技术中的媒体主要是指（ ）。", "options": [{"letter": "A", "text": "表示媒体"}, {"letter": "B", "text": "感觉媒体"}, {"letter": "C", "text": "显示媒体"}, {"letter": "D", "text": "存储媒体"}], "answer": "B", "explanation": "多媒体中的媒体按作用可分为感觉、表示、显示、存储和传输五类，其中感觉媒体指直接作用于人的视觉、听觉等感官、使人产生直接感觉的文字、声音、图像等，是多媒体技术面向用户的核心对象，因此选B。最易混淆的是A，表示媒体只是感觉媒体为便于计算机处理而采用的编码形式，如文本编码、图像编码，并非媒体本身所指的对象。"}, {"id": 280, "section": "信息技术基础专题", "num": 232, "stem": "下面的图形图像文件格式中，（ ）可实现动画。", "options": [{"letter": "A", "text": "GIF格式"}, {"letter": "B", "text": "WMF格式"}, {"letter": "C", "text": "BMP格式"}, {"letter": "D", "text": "JPG格式"}], "answer": "A", "explanation": "GIF采用无损压缩并支持多帧存储，可将多幅图像按时间顺序播放从而实现动画，是早期网络动画的常用格式。JPG最容易混淆，它采用有损压缩、色彩丰富，适合保存照片等静态图像，但只能存储单帧画面，因此无法实现动画。"}];
